var e={entries:JSON.parse(`{"assign":{"short":"Met la valeur de droite dans le nom de gauche.","simple":"Comme écrire un nouveau nombre sur une boîte étiquetée : ce qu'il y avait dedans avant a disparu.","deep":"C'est une affectation, pas une question : pour comparer, on utilise <code>==</code>. Dans une déclaration comme <code>uint8_t r = 0;</code>, le <code>=</code> donne à la variable sa première valeur (initialisation)."},"arithmetic":{"short":"Additionner, soustraire et diviser, comme sur une calculatrice.","simple":"Les maths de l'école, avec une surprise : diviser deux nombres entiers jette le reste, donc <code>7 / 2</code> vaut <code>3</code>.","deep":"La division entière tronque vers zéro ; écris <code>7 / 2.0f</code> pour obtenir <code>3.5</code>. Les petits types comme <code>uint8_t</code> sont promus en <code>int</code> avant le calcul, donc <code>pos * 3</code> ne peut pas déborder avant d'être restocké."},"modulo":{"short":"Le reste après une division : <code>7 % 3</code> vaut <code>1</code>.","simple":"Comme un cadran d'horloge : tu comptes au-delà de 12 et tu repars de 1. C'est ce qui rend <code>%</code> parfait pour tout ce qui tourne en rond.","deep":"Ne marche que sur les nombres entiers (utilise <code>fmodf</code> pour les flottants). Avec un côté gauche négatif, le résultat est négatif aussi : <code>-1 % 6</code> vaut <code>-1</code>, pas <code>5</code>."},"compound-assign":{"short":"Raccourci qui met à jour une variable à partir de sa propre valeur : <code>x += 5</code> veut dire <code>x = x + 5</code>.","simple":"Comme recharger un bocal : tu ne le vides pas pour le remplir à nouveau, tu en rajoutes juste un peu.","deep":"Le côté gauche n'est évalué qu'une fois, ce qui compte quand c'est par exemple <code>buf_[i++]</code>. Le résultat est reconverti dans le type de la variable, donc un <code>uint8_t</code> repasse discrètement à 0 après 255."},"increment":{"short":"Ajoute un (<code>++</code>) ou retire un (<code>--</code>) à une variable.","simple":"Un compteur à clic : un clic, un de plus.","deep":"<code>i++</code> renvoie l'ancienne valeur puis ajoute un ; <code>++i</code> ajoute d'abord. Dans une boucle <code>for</code>, seuls, ils se comportent pareil. Un <code>uint8_t hue</code> non signé repasse de 255 à 0, ce sur quoi s'appuie l'arc-en-ciel de la leçon 01."},"compare":{"short":"Compare deux valeurs et répond <code>true</code> ou <code>false</code> ; après un nom de type, &lt; &gt; contiennent un type à la place.","simple":"Des questions dont la réponse est oui/non : est-ce égal ? est-ce plus petit ? Remarque le double <code>==</code> : un seul <code>=</code> changerait la valeur au lieu de poser la question.","deep":"Comparer un signé avec un non signé convertit le côté signé en non signé, donc <code>-1 &lt; 1u</code> est faux ; le compilateur t'avertit. Dans <code>std::vector&lt;Card&gt;</code> ou <code>static_cast&lt;int&gt;</code>, les chevrons sont des chevrons de template, pas des comparaisons."},"logic":{"short":"Combine des réponses oui/non : <code>&amp;&amp;</code> veut dire et, <code>||</code> veut dire ou, <code>!</code> veut dire non.","simple":"« S'il pleut <b>et</b> que je suis dehors, j'ouvre le parapluie. » <code>!</code> inverse une réponse : il ne pleut pas.","deep":"Court-circuit : <code>a &amp;&amp; b</code> ne regarde jamais <code>b</code> quand <code>a</code> est faux, c'est pourquoi <code>queue_ &amp;&amp; xQueueReceive(queue_, ...)</code> est sûr avec une file nulle. Après un type (<code>T &amp;&amp;</code>), le double esperluette désigne plutôt une référence déplaçable."},"ternary":{"short":"Un if/else sur une ligne qui choisit une valeur : <code>test ? this : that</code>.","simple":"« Le HUD est-il actif ? Alors dis 'on', sinon dis 'off'. » Une question avec deux réponses possibles.","deep":"Les deux branches doivent être convertibles vers un type commun. Seule la branche choisie est évaluée, donc on peut s'en servir pour protéger une division ou un pointeur."},"shift":{"short":"Fait glisser les bits d'un nombre à gauche ou à droite ; un cran à gauche le double, un cran à droite le divise par deux.","simple":"Comme déplacer les chiffres d'un nombre le long d'une rangée d'interrupteurs : tout glisse et un nouveau 0 arrive au bout.","deep":"Sert à empaqueter et dépaqueter des octets : <code>(r &amp; 0xF8) &lt;&lt; 8</code> place le rouge dans les 5 bits de poids fort d'une couleur RGB565. Décaler d'une largeur égale ou supérieure à celle du type est un comportement indéfini."},"bit-ops":{"short":"Travaillent sur les bits individuels d'un nombre : <code>|</code> met des bits à 1, <code>^</code> les inverse, <code>~</code> les inverse tous.","simple":"Imagine un nombre comme une rangée de 8, 16 ou 32 interrupteurs. Ces opérateurs basculent certains interrupteurs sans toucher aux autres.","deep":"<code>flags |= bit</code> active un bit, <code>flags &amp;= ~bit</code> le désactive, <code>flags ^= bit</code> le bascule. Les pilotes de registres comme notre MFRC522 vivent là-dessus. ArduinoJson réutilise <code>|</code> pour une valeur par défaut : <code>in[\\"type\\"] | \\"\\"</code>."},"scope":{"short":"Va chercher un nom à l'intérieur d'un namespace, d'une classe ou d'une enum : <code>std::min</code> est le <code>min</code> qui vit dans <code>std</code>.","simple":"Comme une adresse : <i>Londres::Baker Street</i>. Deux rues peuvent porter le même nom tant qu'elles sont dans des villes différentes.","deep":"L'opérateur de résolution de portée. <code>Button::Event::Click</code> descend de deux niveaux ; un <code>::</code> au début (comme dans <code>::ble::activity()</code>) part du namespace global, donc un nom local ne peut jamais le masquer."},"arrow":{"short":"Utilise un membre de ce que pointe un pointeur : <code>p->x</code> équivaut à <code>(*p).x</code>.","simple":"Un point (<code>.</code>) parle à un objet que tu tiens ; la flèche parle à un objet dont tu n'as que l'adresse.","deep":"Accès à un membre via un pointeur. Les gestionnaires web reçoivent <code>AsyncWebServerRequest *req</code>, donc on écrit <code>req->send(...)</code>. Suivre un <code>nullptr</code> plante l'ESP32 avec une panique LoadProhibited ou StoreProhibited, donc on vérifie les pointeurs d'abord."},"maths":{"short":"Des fonctions mathématiques de la bibliothèque C : sinus, cosinus, racine carrée, arrondi, valeur absolue et compagnie.","simple":"Les touches scientifiques d'une calculatrice, prêtes à l'emploi dans le code. Les angles sont en radians : un tour complet fait environ 6,283.","deep":"Les versions en <code>f</code> (<code>sinf</code>, <code>sqrtf</code>) travaillent sur des <code>float</code>, que le FPU matériel de l'ESP32-S3 gère vite ; les versions <code>double</code> tournent par logiciel et sont plusieurs fois plus lentes. <code>lroundf</code> arrondit à l'entier le plus proche."},"snprintf":{"short":"Construit un morceau de texte à partir d'un modèle et de valeurs, dans une boîte de taille fixe.","simple":"Un formulaire à trous : <code>\\"%d/%d\\"</code> a deux trous, et les nombres que tu passes les remplissent dans l'ordre.","deep":"<code>snprintf(buf, sizeof(buf), fmt, ...)</code> n'écrit jamais au-delà du tampon et termine toujours le texte par un <code>'\\\\0'</code> ; un texte trop long est coupé. Mêmes codes <code>%</code> que <code>Serial.printf</code> : <code>%d</code> int, <code>%u</code> unsigned, <code>%lu</code> unsigned long, <code>%.1f</code> float, <code>%s</code> texte, <code>%02X</code> hexa."},"void":{"short":"Veut dire « rien » : une fonction <code>void</code> fait son travail mais ne rend aucune valeur.","simple":"Comme une sonnette : tu appuies et quelque chose se passe, mais elle ne te donne rien à tenir.","deep":"Comme type de retour, il veut dire aucun résultat. <code>void *</code> est un pointeur vers une mémoire de type inconnu, comme le <code>void *arg</code> que reçoivent les tâches FreeRTOS et les gestionnaires d'interruption ; il faut le reconvertir avant usage."},"bool":{"short":"Une valeur oui/non : soit <code>true</code>, soit <code>false</code>.","simple":"Un interrupteur : allumé ou éteint, rien entre les deux.","deep":"Occupe un octet. Les nombres et les pointeurs se convertissent automatiquement en <code>bool</code> (zéro et <code>nullptr</code> sont faux), c'est pourquoi <code>if (buf_)</code> fonctionne. Le <code>boolean</code> d'Arduino est le même type."},"true-false":{"short":"Les deux valeurs que peut contenir un <code>bool</code>.","simple":"Oui et non, écrits comme le compilateur les comprend.","deep":"Des mots-clés de type <code>bool</code> ; convertis en nombres, ils deviennent 1 et 0. FreeRTOS utilise ses propres <code>pdTRUE</code>/<code>pdFALSE</code> pour la même idée."},"int":{"short":"Un nombre entier qui peut être négatif, le choix par défaut de tous les jours pour compter.","simple":"Une boîte pour des nombres entiers comme -3, 0 ou 42. Pas de fractions.","deep":"Sur l'ESP32, un <code>int</code> fait 32 bits : d'environ -2,1 milliards à +2,1 milliards. Sa taille varie selon les puces (16 bits sur un Arduino Uno), c'est pourquoi le code matériel préfère souvent <code>int32_t</code> et ses amis, qui annoncent leur taille."},"long":{"short":"Un type d'entier au moins aussi grand qu'un <code>int</code> ; sur l'ESP32, les deux font 32 bits.","simple":"Une autre boîte pour des nombres entiers. Sur cette puce, elle contient exactement ce que contient un <code>int</code>.","deep":"<code>long</code> fait 32 bits sur l'ESP32 Xtensa et <code>long long</code> en fait 64. <code>millis()</code> renvoie un <code>unsigned long</code>, donc l'afficher demande <code>%lu</code> ; le code fait souvent un cast avec <code>static_cast&lt;unsigned long&gt;</code> pour que ça colle exactement."},"unsigned":{"short":"Un nombre entier qui ne peut pas descendre sous zéro, donc il monte deux fois plus haut.","simple":"Comme le compteur kilométrique d'une voiture : il ne fait que compter à partir de 0, et après son dernier chiffre il repasse à 0.","deep":"Le calcul non signé boucle au lieu de déborder : <code>0u - 1</code> est la plus grande valeur. Cette boucle est justement ce qui fait que <code>now - last >= interval</code> continue de marcher quand <code>millis()</code> repasse à zéro. <code>unsigned(x)</code> est un cast rapide, pratique pour <code>%u</code> dans printf."},"float":{"short":"Un nombre à virgule, comme <code>3.14</code> ou <code>-0.5</code>.","simple":"Une règle aux graduations fines : bien pour mesurer, mais de minuscules erreurs d'arrondi s'invitent, donc ne teste jamais l'égalité exacte de deux flottants.","deep":"32 bits, environ 7 chiffres significatifs. L'ESP32-S3 a un FPU en simple précision, donc le calcul en <code>float</code> est rapide ; écris les constantes <code>0.5f</code> pour que le compilateur ne passe pas au <code>double</code> lent."},"double":{"short":"Un nombre décimal avec environ deux fois la précision d'un <code>float</code>.","simple":"La même règle que <code>float</code>, avec des graduations encore plus fines, mais plus lente à lire sur cette puce.","deep":"64 bits, environ 15 chiffres significatifs. Le FPU de l'ESP32-S3 ne fait que la simple précision, donc <code>double</code> est calculé par logiciel : correct pour un calcul occasionnel, trop lent pour chaque pixel ou échantillon audio."},"char":{"short":"Un caractère de texte, stocké comme un petit nombre ; <code>const char *</code> est un texte entier.","simple":"Une seule tuile-lettre d'un jeu de mots. Aligne des tuiles, termine par une tuile d'arrêt invisible <code>'\\\\0'</code>, et tu as un mot.","deep":"Un octet. Une chaîne C est un tableau de <code>char</code> qui finit par <code>'\\\\0'</code> ; <code>char text[32]</code> contient jusqu'à 31 lettres. <code>\\"hello\\"</code> est un <code>const char *</code> vers du texte gardé en flash, alors que <code>'h'</code> (guillemets simples) est un seul <code>char</code>."},"size-t":{"short":"Un entier non signé fait pour les tailles et les nombres d'éléments en mémoire.","simple":"Le chiffre sur un mètre ruban de la mémoire : combien d'octets, combien d'éléments. Il ne peut jamais être négatif.","deep":"32 bits sur l'ESP32, le type que donne <code>sizeof</code> et que prend <code>malloc</code>. Affiche-le avec <code>%u</code> après un cast, ou <code>%zu</code>."},"uint8-t":{"short":"Un nombre entier de 0 à 255 : exactement un octet.","simple":"La plus petite boîte : un octet, huit interrupteurs on/off. Parfaite pour un canal de couleur, un numéro de broche ou une luminosité.","deep":"<code>u</code> = unsigned, <code>int</code>, <code>8</code> bits, <code>_t</code> = un type. Défini dans <code>&lt;stdint.h&gt;</code>, donc sa taille est la même sur toutes les puces. Le <code>byte</code> d'Arduino est le même type. Après 255, il repasse à 0."},"uint16-t":{"short":"Un nombre entier de 0 à 65 535 : deux octets.","simple":"Une boîte deux fois plus grande qu'un octet. Chaque couleur d'écran de ces labos y tient.","deep":"Non signé, 16 bits. Le ST7789 parle RGB565 : 5 bits de rouge, 6 de vert, 5 de bleu, rangés dans un seul <code>uint16_t</code>. Sert aussi pour les handles BLE et les UUID de 16 bits."},"uint32-t":{"short":"Un nombre entier de 0 à environ 4,29 milliards : quatre octets.","simple":"Une grande boîte pour de grands comptes, comme les millisecondes depuis le démarrage de la carte.","deep":"Non signé, 32 bits : la taille de mot naturelle de l'ESP32, donc lire et écrire une telle valeur tient en une seule instruction. Les temps de <code>millis()</code> y vivent et repassent à zéro après environ 49,7 jours."},"uint64-t":{"short":"Un énorme nombre entier, de 0 à environ 18 trillions : huit octets.","simple":"Une boîte si grande qu'elle ne se remplit jamais en pratique. L'adresse MAC de 48 bits de la puce y tient largement.","deep":"Non signé, 64 bits. Sur un CPU 32 bits, chaque opération prend quelques instructions, et en lire une partagée entre une interruption et le code principal n'est pas atomique, donc les labos gardent les horodatages partagés sur 32 bits."},"int8-t":{"short":"Un petit nombre entier de -128 à 127 : un octet qui peut être négatif.","simple":"Une boîte d'un octet avec la place d'un signe moins. Bien pour des choses comme la puissance du signal Wi-Fi en dBm.","deep":"Signé, 8 bits, complément à deux. La puissance d'émission BLE et les valeurs RSSI sont rapportées en <code>int8_t</code>."},"int16-t":{"short":"Un nombre entier de -32 768 à 32 767 : deux octets qui peuvent être négatifs.","simple":"Une boîte de deux octets avec un signe moins. Les coordonnées d'écran l'utilisent, donc des formes peuvent commencer juste hors du bord.","deep":"Signé, 16 bits. Adafruit GFX prend des <code>int16_t</code> pour x, y, largeur et hauteur, et les échantillons audio 16 bits du microphone sont aussi des <code>int16_t</code>."},"int32-t":{"short":"Un nombre entier d'environ -2,1 milliards à +2,1 milliards : quatre octets qui peuvent être négatifs.","simple":"La même boîte que <code>int</code> sur cette puce, mais son nom promet la taille sur toutes les puces.","deep":"Signé, 32 bits. Le microphone INMP441 envoie des échantillons de 24 bits dans des slots I2S de 32 bits, lus comme <code>int32_t</code> puis décalés vers le bas."},"int64-t":{"short":"Un énorme nombre entier qui peut être négatif : huit octets.","simple":"Une boîte qui ne manque jamais pour des horloges qui comptent des microsecondes.","deep":"Signé, 64 bits. <code>esp_timer_get_time()</code> renvoie des microsecondes depuis le démarrage en <code>int64_t</code>, qui mettraient environ 292 000 ans à déborder."},"string-class":{"short":"Le type de texte d'Arduino : un texte qui peut grandir, rétrécir et être fouillé.","simple":"Une page de carnet extensible pour des mots : ajoute dessus, découpe des morceaux, cherche un mot, sans compter les lettres toi-même.","deep":"Garde ses lettres dans le tas (les courtes en place), donc des <code>+</code> répétés dans une boucle chargée brassent la mémoire. Les labos utilisent <code>String</code> pour les commandes série et les réponses web, et des tableaux <code>char</code> fixes là où la vitesse ou les interruptions comptent. <code>String(42)</code> transforme un nombre en texte."},"auto":{"short":"Laisse le compilateur déduire le type à partir de la valeur que tu donnes.","simple":"Comme dire « mets-le dans une boîte de la bonne taille » au lieu de nommer la boîte.","deep":"Le type reste fixé à la compilation, il n'est pas dynamique. <code>auto *self = static_cast&lt;Button *&gt;(arg);</code> évite d'écrire <code>Button</code> deux fois ; <code>auto</code> est aussi la façon de stocker des lambdas, puisque leur type n'a pas de nom."},"nullptr":{"short":"Un pointeur qui ne pointe sur rien.","simple":"Une étiquette d'adresse vide : il n'y a pas de maison à visiter, donc vérifie avant d'y aller.","deep":"La constante de pointeur nul sûre au niveau des types (C++11), qui remplace <code>NULL</code> et <code>0</code>. Les fonctions d'allocation comme <code>heap_caps_malloc</code> le renvoient en cas d'échec, et beaucoup d'appels ESP-IDF le prennent pour dire « je n'en ai pas besoin »."},"if":{"short":"Exécute le bloc suivant seulement quand le test entre parenthèses est vrai.","simple":"« S'il pleut, prends un parapluie. » Quand il ne pleut pas, l'étape du parapluie est sautée.","deep":"La condition est convertie en <code>bool</code>, donc les nombres et les pointeurs marchent directement. Une déclaration dans le test (<code>if (DeserializationError e = deserializeJson(...))</code>) garde la variable à l'intérieur du if."},"else":{"short":"L'autre chemin : s'exécute quand le test du <code>if</code> était faux.","simple":"« ...sinon, mets des lunettes de soleil. » Un seul des deux chemins a lieu.","deep":"<code>else if</code> n'est qu'un <code>else</code> dont le bloc est un autre <code>if</code>, donc les chaînes sont vérifiées de haut en bas et s'arrêtent au premier test vrai."},"for":{"short":"Répète un bloc un nombre compté de fois, ou une fois pour chaque élément d'une liste.","simple":"« Pour chacun des 6 octets, affiche-le. » Commence à 0, vérifie que tu n'as pas fini, fais le travail, compte un de plus, recommence.","deep":"<code>for (init; test; step)</code>. La forme sur plage <code>for (const auto &amp;card : cards)</code> visite chaque élément d'un tableau ou d'un conteneur sans indice."},"while":{"short":"Répète un bloc tant que son test reste vrai.","simple":"« Tant qu'il y a des lettres dans la boîte aux lettres, prends-en une. » Quand elle est vide, arrête.","deep":"Le test s'exécute avant chaque tour, donc le corps peut s'exécuter zéro fois. Un <code>while</code> sans fin dans <code>loop()</code> affame le reste du programme ; les labos lisent l'entrée avec <code>while (Serial.available())</code>, qui s'arrête dès que le tampon est vide."},"do-while":{"short":"Comme <code>while</code>, mais le bloc s'exécute toujours au moins une fois avant le test.","simple":"Goûte la soupe, puis décide si elle manque de sel. Tu goûtes toujours d'abord.","deep":"Le test est après le corps et demande un point-virgule : <code>do { ... } while (cond);</code>. Pratique pour « tire une valeur au hasard jusqu'à ce qu'elle convienne »."},"switch":{"short":"Choisit un chemin parmi plusieurs en comparant une valeur à des choix fixes.","simple":"Un tableau d'ascenseur : appuie sur 3 et tu vas à l'étage 3. Chaque <code>case</code> est un bouton.","deep":"Marche sur les nombres entiers et les enums, pas sur le texte. L'exécution tombe dans le cas suivant sauf si tu fais <code>break</code> ou <code>return</code>. Avec une <code>enum class</code>, le compilateur te prévient des cas oubliés."},"case":{"short":"Un choix à l'intérieur d'un <code>switch</code> : le code à exécuter quand la valeur correspond.","simple":"Un bouton du tableau d'ascenseur, avec son étage écrit à côté.","deep":"L'étiquette doit être une constante connue à la compilation. Plusieurs étiquettes peuvent partager un corps en les empilant ; un corps sans <code>break</code> se poursuit dans le cas suivant."},"default":{"short":"Dans un <code>switch</code>, le chemin pris quand aucun <code>case</code> ne correspond.","simple":"Le bouton « tout le reste ».","deep":"Facultatif et peut se placer n'importe où dans le switch. Dans une classe, <code>= default</code> veut dire autre chose : demander au compilateur d'écrire ce constructeur ou cet opérateur pour toi."},"break":{"short":"Quitte immédiatement la boucle ou le <code>switch</code> en cours.","simple":"Une sortie de secours : arrête de tourner, continue après la boucle.","deep":"Ne quitte que la boucle ou le switch le plus interne. Dans un switch placé dans une boucle, <code>break</code> quitte le switch, pas la boucle."},"continue":{"short":"Saute la fin de ce tour de boucle et commence le suivant.","simple":"« Cette lettre n'est pas pour moi : je la mets de côté et j'ouvre la suivante. »","deep":"Dans une boucle <code>for</code>, le pas (<code>i++</code>) s'exécute quand même avant le test suivant. Souvent utilisé pour écarter tôt les mauvaises données au lieu d'imbriquer des <code>if</code>."},"return":{"short":"Termine la fonction tout de suite, en rendant éventuellement une valeur à celui qui l'a appelée.","simple":"Rendre le devoir terminé : le travail est fait et voici la réponse.","deep":"Dans une fonction <code>void</code>, un simple <code>return;</code> sort en avance, une façon courante de s'échapper sur une mauvaise entrée (une clause de garde). Les variables locales sont détruites à la sortie, c'est ainsi que <code>std::lock_guard</code> déverrouille."},"setup-loop":{"short":"Tout programme Arduino a ces deux fonctions : <code>setup()</code> s'exécute une fois à la mise sous tension, puis <code>loop()</code> tourne sans fin.","simple":"Ouvrir une boutique : <code>setup()</code> déverrouille la porte et allume les lumières une fois ; <code>loop()</code> sert client après client jusqu'à la fermeture (mise hors tension).","deep":"Le <code>main</code> du cœur Arduino démarre une tâche FreeRTOS (« loopTask », cœur 1, pile de 8 KB par défaut) qui appelle <code>setup()</code> puis <code>loop()</code> encore et encore. Garde <code>loop()</code> rapide et non bloquante : vérifie <code>millis()</code> au lieu de longs <code>delay()</code>. Le <code>lab.loop()</code> d'un labo est le travail par tour de la coque."},"lambda":{"short":"Une petite fonction écrite juste là où on en a besoin, souvent passée à une autre fonction pour être appelée plus tard.","simple":"Un pense-bête d'instructions que tu tends à quelqu'un : « quand une requête pour / arrive, fais ça ».","deep":"<code>[capture](params) { body }</code>. La liste de capture dit ce qu'elle peut utiliser autour d'elle : <code>[this]</code> l'objet courant, <code>[&amp;]</code> tout par référence, <code>[]</code> rien. Les routes web, les événements Wi-Fi et les tris prennent ici des lambdas."},"variadic":{"short":"Veut dire « n'importe quel nombre d'arguments en plus », comme les valeurs dont a besoin un modèle printf.","simple":"« ...et ainsi de suite » : la fonction prend autant de suppléments que tu lui en donnes.","deep":"Dans <code>void warn(const char *fmt, ...)</code>, les suppléments sont lus avec <code>va_list</code> et transmis à <code>vsnprintf</code> ; l'attribut <code>[[gnu::format(printf, 2, 3)]]</code> laisse le compilateur les vérifier par rapport au modèle. Dans une macro, <code>__VA_ARGS__</code> les colle."},"inline":{"short":"Permet de définir une fonction ou une variable dans un en-tête inclus par de nombreux fichiers.","simple":"Une recette imprimée dans chaque livre de cuisine qui en a besoin : la cuisine convient que c'est la même recette partout, pas des rivales.","deep":"Son vrai rôle est la règle de définition unique : une fonction <code>inline</code> dans un <code>.h</code> peut apparaître dans de nombreux <code>.cpp</code> sans conflit de l'éditeur de liens. Que l'appel soit réellement mis en ligne dépend de l'optimiseur. Les fonctions <code>constexpr</code> et celles définies dans une classe sont inline automatiquement."},"operator":{"short":"Apprend à un type ce qu'un symbole comme <code>==</code>, <code>[]</code> ou <code>+</code> doit faire avec lui.","simple":"Comme apprendre les règles existantes à un nouveau pion : maintenant <code>a == b</code> marche aussi pour ta propre sorte de chose.","deep":"<code>bool operator==(const Uid &amp;o) const</code> n'est qu'une fonction avec un nom spécial ; <code>explicit operator bool()</code> permet de tester un objet dans un <code>if</code>."},"noexcept":{"short":"Une promesse qu'une fonction ne lèvera jamais d'exception.","simple":"Un panneau sur la porte : « pas de surprise ici ».","deep":"Si elle en lève une quand même, <code>std::terminate</code> arrête le programme. Les conteneurs standard s'en servent pour décider si déplacer un élément est sûr. Arduino-ESP32 se compile avec les exceptions disponibles, mais les labos n'en lèvent jamais."},"override":{"short":"<code>virtual</code> laisse une classe fille remplacer une fonction ; <code>override</code> marque le remplacement.","simple":"Un formulaire avec un blanc : la bibliothèque laisse « comment dessiner un pixel » à remplir, et <code>override</code> dit « voici ma réponse à ce blanc ».","deep":"Les appels passent par une table de pointeurs de fonctions (la vtable), donc le code d'<code>Adafruit_GFX</code> finit par appeler notre <code>FrameBuffer::drawPixel</code>. <code>override</code> fait vérifier au compilateur qu'une fonction virtuelle correspondante existe. Les callbacks NimBLE comme <code>onConnect</code> fonctionnent pareil."},"explicit":{"short":"Empêche le compilateur de transformer discrètement un type en un autre via un constructeur.","simple":"« Demande d'abord » : un nombre ne devient pas un <code>Button</code> juste parce qu'un <code>Button</code> peut être construit à partir de lui.","deep":"Sans lui, un constructeur à un argument est une conversion implicite, donc une fonction qui prend un <code>BootButton</code> pourrait être appelée avec un simple nombre. Aussi utilisé sur <code>operator bool</code>."},"constructor":{"short":"Une fonction spéciale portant le nom de la classe qui prépare un nouvel objet.","simple":"La notice de montage qui s'exécute une fois quand une nouvelle chose sort de la boîte.","deep":"Pas de type de retour. La liste après <code>:</code> (<code>: pin_(pin), name_(name)</code>) remplit les membres avant que le corps s'exécute, dans l'ordre où ils sont déclarés. Un destructeur <code>~Name()</code> s'exécute quand l'objet disparaît, comme <code>FrameBuffer</code> qui libère ses pixels."},"address-reference":{"short":"Trois rôles : après un type, il fait une référence (un autre nom) ; devant une variable, il prend son adresse ; entre deux nombres, c'est un ET bit à bit.","simple":"Une référence est un surnom : <code>uint8_t &amp;r</code> laisse une fonction écrire directement dans ta boîte. <code>&amp;x</code> est l'adresse postale de la boîte. <code>a &amp; b</code> ne garde que les bits à 1 dans les deux.","deep":"<code>T &amp;</code> se lie à un objet existant et ne peut être ni nulle ni repointée ; <code>const T &amp;</code> passe de gros objets sans copie. <code>&amp;lock_</code> donne un <code>portMUX_TYPE *</code>. <code>x &amp; 0xFF</code> masque l'octet de poids faible."},"pointer":{"short":"Trois rôles : après un type, il déclare un pointeur ; devant un pointeur, il le suit ; entre deux nombres, il multiplie.","simple":"Un pointeur est un bout de papier avec une adresse dessus. <code>*p</code> veut dire « va à cette adresse et utilise ce qu'il y a ». Entre deux nombres, c'est juste fois.","deep":"Les pointeurs font 4 octets sur l'ESP32. <code>uint16_t *buf_</code> contient l'endroit où commencent les pixels ; <code>buf_[i]</code> équivaut à <code>*(buf_ + i)</code>. <code>const char *</code> est un pointeur vers un texte que tu peux lire mais pas modifier."},"array":{"short":"Une rangée fixe de valeurs du même type, numérotées à partir de 0.","simple":"Une boîte à œufs : un nombre fixe de cases, toutes de la même forme. Les numéros de case commencent à 0, donc une boîte de 6 cases a les cases 0 à 5.","deep":"<code>char text[32]</code> réserve 32 octets sur place, sans tas. Rien ne vérifie l'indice, donc écrire <code>text[32]</code> piétine discrètement ce qui se trouve à côté ; <code>sizeof(text)</code> donne la taille totale en octets, c'est pourquoi les appels de tampon la passent."},"const":{"short":"Marque une valeur comme en lecture seule : une fois fixée, le code ne peut plus la changer.","simple":"Une étiquette écrite au stylo, pas au crayon.","deep":"Contrairement à <code>constexpr</code>, la valeur peut venir de code exécuté (<code>const uint32_t now = millis();</code>). Après les parenthèses d'une fonction membre, <code>const</code> promet que la fonction ne modifiera pas l'objet. <code>const char *p</code> protège le texte ; <code>char *const p</code> protège le pointeur."},"static":{"short":"Garde une variable en vie pendant tout le programme, ou partage une seule copie entre tous les objets d'une classe.","simple":"Dans une fonction, c'est un carnet qui reste sur le bureau entre les visites, donc <code>loop()</code> se souvient de sa dernière valeur.","deep":"Trois sens. Une locale <code>static</code> est créée une fois et survit entre les appels. Un membre <code>static</code> appartient à la classe, pas à chaque objet (le gestionnaire d'interruption <code>onEdge</code> est static et reçoit l'objet par <code>arg</code>). Au niveau du fichier, il rend un nom privé à ce fichier."},"volatile":{"short":"Dit au compilateur que cette valeur peut changer dans son dos, donc il doit la relire à chaque fois.","simple":"Une boîte aux lettres qui peut se remplir quand tu ne regardes pas : il faut aller vérifier, pas supposer qu'elle est encore vide.","deep":"Nécessaire pour les variables écrites par une interruption et lues par le code normal. Ce n'est <b>pas</b> un verrou et ce n'est pas atomique : une valeur de 64 bits peut quand même être lue de travers. Pour des données partagées entre tâches, préfère <code>std::atomic</code>, un mutex ou une section critique."},"sizeof":{"short":"Te dit combien d'octets prend un type ou une variable.","simple":"Comme lire la contenance imprimée sur un bocal avant d'y verser quoi que ce soit.","deep":"Calculé à la compilation, il ne coûte rien à l'exécution. <code>sizeof(text)</code> d'un tableau est sa taille totale en octets, mais pour un pointeur c'est juste 4. <code>sizeof(arr) / sizeof(arr[0])</code> compte les éléments."},"new-delete":{"short":"<code>new</code> construit un objet dans la mémoire libre (le tas) ; <code>delete</code> le détruit et rend la mémoire.","simple":"Louer un box de stockage : <code>new</code> en loue un, <code>delete</code> rend la clé. Oublie de la rendre et la place est perdue jusqu'au redémarrage.","deep":"Chaque <code>new</code> demande exactement un <code>delete</code> (<code>new[]</code> demande <code>delete[]</code>). Sur l'ESP32, un simple <code>new</code> peut atterrir en RAM interne ou en PSRAM selon la taille et les réglages de compilation ; pour choisir, utilise <code>heap_caps_malloc</code>. <code>= delete</code> sur une fonction l'interdit, par exemple la copie."},"progmem":{"short":"Demande que des données restent en mémoire flash au lieu d'être copiées en RAM.","simple":"Laisser le gros livre sur l'étagère de la bibliothèque et le lire là, au lieu de le photocopier sur ton petit bureau.","deep":"Essentiel sur les Arduino AVR ; sur l'ESP32, il est défini comme rien, parce que les données <code>const</code> restent déjà dans la flash mappée en mémoire. On le garde pour la clarté et la portabilité, comme pour la page web dans <code>kPage</code>."},"iram-attr":{"short":"Place une fonction dans la RAM interne rapide de la puce, pour qu'elle puisse s'exécuter à l'instant où une interruption se déclenche.","simple":"Garder l'extincteur près de la porte plutôt qu'à la cave : il faut pouvoir l'attraper tout de suite.","deep":"Le code normal s'exécute depuis la flash externe via un cache, et le cache est coupé pendant l'écriture en flash (NVS, OTA). Un gestionnaire d'interruption logé en flash ferait alors planter la puce ; <code>IRAM_ATTR</code> le garde en IRAM. Tout ce qu'il appelle devrait aussi être en IRAM, donc garde les gestionnaires minuscules."},"c-strings":{"short":"Les outils du C pour le texte dans des tableaux <code>char</code> : le copier, le comparer, le mesurer.","simple":"Travailler les tuiles-lettres à la main : copie un mot sur ta rangée, compare deux rangées, compte les tuiles avant la tuile d'arrêt.","deep":"<code>strlcpy(dst, src, sizeof(dst))</code> copie en sécurité et termine toujours par <code>'\\\\0'</code>. <code>strcmp</code> renvoie 0 quand deux textes sont égaux (pas true !), donc le code écrit <code>strcmp(a, b) == 0</code>. <code>strlen</code> compte les lettres, pas le <code>'\\\\0'</code> final."},"memcpy":{"short":"Copier, remplir ou comparer un bloc d'octets bruts.","simple":"Déplacer un plateau entier d'œufs d'un coup au lieu d'un œuf à la fois.","deep":"Elles travaillent sur des octets et ne savent rien des types : la longueur est toujours en octets, donc utilise <code>sizeof</code>. <code>memcpy</code> ne doit pas se chevaucher (utilise <code>memmove</code>) ; <code>memcmp</code> renvoie 0 pour égal. Les UID de cartes et les charges BLE se traitent ainsi."},"struct":{"short":"Regroupe plusieurs valeurs nommées en un nouveau type.","simple":"Un formulaire avec des champs étiquetés : une Card a un UID, un nom et une couleur, et ils voyagent ensemble.","deep":"Identique à <code>class</code> sauf que les membres sont <code>public</code> par défaut. Les labos utilisent des structs pour les données simples (<code>HttpsResult</code>, <code>Frame</code>) et des classes pour les choses qui ont un comportement."},"class":{"short":"Définit un nouveau genre d'objet : les données qu'il garde et ce qu'il sait faire.","simple":"Le plan d'un gadget : quelles pièces il a à l'intérieur et quels boutons sont à l'extérieur.","deep":"Les membres sont <code>private</code> par défaut. <code>class FrameBuffer : public Adafruit_GFX</code> hérite de tout ce que sait faire une surface de dessin GFX. <code>enum class</code> réutilise le mot pour autre chose : une enum à portée."},"enum":{"short":"Une liste de choix nommés, comme <code>Click</code>, <code>DoubleClick</code>, <code>LongPress</code>.","simple":"Une question à choix multiples : la réponse doit être l'une des options imprimées sur la feuille.","deep":"<code>enum class Event { ... }</code> a une portée (on écrit <code>Event::Click</code>) et ne se transforme pas en <code>int</code> par accident. <code>: uint8_t</code> choisit le type de stockage. Une <code>enum</code> simple déverse ses noms dans la portée environnante."},"namespace":{"short":"Un dossier nommé pour des fonctions et des types, pour que les noms de parties différentes n'entrent jamais en conflit.","simple":"Des noms de famille pour le code : <code>pal::ink</code> et <code>sv::ink</code> peuvent coexister, comme deux personnes appelées Sam dans des familles différentes.","deep":"Un <code>namespace { }</code> sans nom rend tout son contenu privé à ce fichier <code>.cpp</code> (liaison interne), comme le fait la leçon 01 avec ses fonctions d'aide. <code>using namespace x;</code> fait ressortir les noms ; évite-le dans les en-têtes."},"std":{"short":"Le namespace de la bibliothèque standard C++ : <code>std::min</code>, <code>std::vector</code>, <code>std::mutex</code>...","simple":"La boîte à outils livrée avec tout compilateur C++. <code>std::</code> dit « prends cet outil dans la boîte standard ».","deep":"Arduino-ESP32 embarque une bibliothèque standard C++ complète (la libstdc++ de GCC), avec conteneurs, algorithmes, <code>&lt;atomic&gt;</code> et <code>&lt;mutex&gt;</code> au-dessus de FreeRTOS. Surveille l'usage du tas : les conteneurs allouent."},"access":{"short":"Décide qui peut utiliser les membres d'une classe : tout le monde, seulement la classe elle-même, ou la classe et ses enfants.","simple":"Les boutons sur le devant d'une radio sont <code>public</code> ; la carte électronique à l'intérieur est <code>private</code>.","deep":"Une classe garde ses données <code>private</code> (ici avec un <code>_</code> final, comme dans <code>pin_</code>) et offre des fonctions <code>public</code>, pour pouvoir changer son intérieur sans casser les appelants. Dans <code>: public Adafruit_GFX</code>, le mot règle comment les membres du parent sont hérités."},"this":{"short":"Dans une fonction membre, un pointeur vers l'objet sur lequel la fonction travaille.","simple":"« Moi » : l'objet qui se désigne lui-même.","deep":"Généralement implicite (<code>pin_</code> veut dire <code>this->pin_</code>). Passé explicitement quand un callback à la C doit retrouver son chemin, comme dans <code>attachInterruptArg(..., onEdge, this, CHANGE)</code> ou le paramètre d'une tâche, et capturé par les lambdas avec <code>[this]</code>."},"using":{"short":"Donne à un type un nom plus court ou plus clair.","simple":"Un surnom : dis <code>JsonFn</code> au lieu de tout le long type à chaque fois.","deep":"<code>using JsonFn = std::function&lt;...&gt;;</code> est la forme moderne de <code>typedef</code> et se lit de gauche à droite. <code>using namespace std;</code> et <code>using Base::f;</code> sont d'autres usages du même mot."},"union":{"short":"Plusieurs membres qui partagent les mêmes octets, donc un seul a du sens à la fois.","simple":"Une place de parking pour plusieurs voitures possibles : c'est celle qui s'est garée en dernier qui est là.","deep":"L'union est aussi grande que son plus grand membre. Lire un membre autre que le dernier écrit est techniquement indéfini en C++ (GCC l'autorise) ; <code>memcpy</code> ou <code>std::bit_cast</code> sont les moyens propres de réinterpréter des octets."},"extern":{"short":"Dit qu'une variable existe, mais qu'elle est définie ailleurs dans le programme.","simple":"« La clé est dans l'autre pièce » : tu peux en parler ici, et l'éditeur de liens va la chercher plus tard.","deep":"Une déclaration sans définition. Le client HTTPS s'en sert pour atteindre le bundle de certificats Mozilla que la compilation lie dans la flash, par les noms de ses symboles d'édition de liens."},"constexpr":{"short":"Une valeur fixée à la compilation du programme, donc elle ne peut jamais changer pendant que la carte tourne.","simple":"Comme un nombre imprimé sur la boîte plutôt qu'écrit sur un pense-bête : réglé avant même que la carte soit alimentée.","deep":"Les variables <code>constexpr</code> sont calculées par le compilateur et ne coûtent aucune RAM à l'exécution ; une fonction <code>constexpr</code> comme <code>rgb()</code> peut s'exécuter à la compilation quand ses entrées sont des constantes. Les labos les nomment <code>kSomething</code>."},"static-cast":{"short":"Convertit une valeur vers un autre type exprès, là où tu peux le voir.","simple":"Verser une boisson dans un autre verre, volontairement et à la vue de tous.","deep":"Vérifié par le compilateur et gratuit à l'exécution pour les types numériques. Courant ici : <code>static_cast&lt;unsigned long&gt;</code> pour coller à <code>%lu</code>, et retransformer un <code>void *</code> en l'objet qu'il était. La forme courte <code>uint8_t(x)</code> fait pareil pour les types simples."},"reinterpret-cast":{"short":"Traite les mêmes octets comme un type complètement différent, sans les changer.","simple":"Lire une page de chiffres comme si c'étaient des lettres : l'encre est la même, seule ta façon de lire change.","deep":"Aucune conversion n'a lieu ; il ne fait que rebaptiser un pointeur (par exemple <code>uint8_t *</code> en <code>const char *</code> pour un tampon d'octets de texte). Facile à mal utiliser : les règles d'alignement et de strict aliasing s'appliquent toujours."},"const-cast":{"short":"Retire <code>const</code> d'un pointeur pour pouvoir le passer à une fonction à l'ancienne.","simple":"Emprunter une étiquette écrite au stylo pour une fonction qui n'accepte que celles au crayon : tu promets qu'elle n'écrira pas vraiment.","deep":"Sûr seulement quand l'objet n'était pas vraiment const au départ, ou quand l'appelé ne le modifie pas (beaucoup d'API C ont juste oublié <code>const</code>). Écrire à travers lui dans des données vraiment const est indéfini."},"template":{"short":"Écrit une fonction ou une classe une seule fois pour n'importe quel type ; le compilateur en fait une copie pour chaque type utilisé.","simple":"Un emporte-pièce : une forme, n'importe quelle pâte. <code>T</code> tient lieu de pâte jusqu'à ce que tu la choisisses.","deep":"<code>template &lt;typename F&gt; void withChip(F &amp;&amp;fn)</code> accepte n'importe quel appelable, lambdas comprises, sans coût à l'exécution. Chaque nouveau type donne une nouvelle copie compilée, donc un usage intensif fait grossir le firmware. Les chevrons fournissent le type : <code>std::vector&lt;Card&gt;</code>."},"std-min-max":{"short":"Rendent le plus petit ou le plus grand de deux valeurs.","simple":"« Le plus bas des deux » et « le plus haut des deux » : pratique pour garder des nombres dans une plage.","deep":"Les deux arguments doivent avoir le même type, ou tu le nommes : <code>std::min&lt;uint32_t&gt;(n, 320)</code>. <code>std::max(0, n - 9)</code> empêche une valeur de descendre sous zéro."},"std-clamp":{"short":"Serre une valeur dans une plage : en dessous du bas, on obtient le bas ; au-dessus du haut, on obtient le haut.","simple":"Une barrière pour enfants dans l'escalier : tu peux te déplacer, mais pas au-delà des barrières aux deux bouts.","deep":"C++17, de <code>&lt;algorithm&gt;</code>. Les trois arguments doivent partager un même type, d'où les <code>0.0f</code> et <code>1.0f</code>. Le <code>constrain()</code> d'Arduino fait le même travail."},"std-algorithms":{"short":"Des boucles toutes faites de la bibliothèque standard : remplir, copier, trier, trouver le plus grand...","simple":"Des gadgets de cuisine : tu pourrais couper à la main, mais le gadget est plus rapide et ne dérape pas.","deep":"De <code>&lt;algorithm&gt;</code>, ils travaillent sur n'importe quelle plage donnée par un pointeur (ou itérateur) de début et de fin, la fin étant un cran après le dernier élément. <code>std::fill_n(buf_, n, c)</code> peint tout un écran ; <code>std::sort</code> prend une lambda qui dit ce que veut dire « vient en premier »."},"std-move":{"short":"Passe le contenu d'un objet à un autre au lieu de le copier.","simple":"Déménager avec les cartons tels quels, au lieu d'acheter une copie de tout pour le nouveau logement.","deep":"Ce n'est qu'un cast vers une référence rvalue (<code>T &amp;&amp;</code>) ; le déplacement réel est fait par le constructeur de déplacement du type qui reçoit. Ensuite la source est valide mais quasi vide, donc ne compte pas sur sa valeur. Peu coûteux pour <code>String</code>, <code>std::vector</code> et <code>std::function</code>."},"std-vector":{"short":"Une liste qui peut grandir et rétrécir, contenant des éléments d'un seul type.","simple":"Un classeur extensible : ajoute des feuilles et il fait de la place, et tu peux toujours dire « donne-moi la feuille 3 ».","deep":"Stocke les éléments dans un seul bloc contigu du tas et le double quand il est plein, ce qui déplace (et peut fragmenter) la mémoire. Les labos remplissent les vecteurs hors des chemins critiques en temps, par exemple en copiant la liste des cartes pour l'écran. <code>v.size()</code>, <code>v.push_back(x)</code>, <code>v[i]</code>."},"std-function":{"short":"Une boîte qui peut contenir n'importe quelle fonction ou lambda d'une forme donnée, à appeler plus tard.","simple":"Une fente pour un pense-bête d'instructions : n'importe quel mot convient, tant qu'il prend les mêmes entrées.","deep":"<code>std::function&lt;void(Card &amp;)&gt;</code> prend une <code>Card &amp;</code> et ne renvoie rien. Flexible mais plus lourde qu'un template : l'appeler est indirect et les grosses captures vont sur le tas. Bien pour les callbacks stockés dans une classe."},"std-atomic":{"short":"Une variable que deux tâches peuvent lire et écrire en même temps sans jamais voir un changement à moitié fait.","simple":"Un seul interrupteur que tout le monde peut basculer : peu importe qui le touche, il est toujours clairement allumé ou éteint.","deep":"<code>std::atomic&lt;bool&gt;</code> et <code>std::atomic&lt;uint32_t&gt;</code> sont sans verrou sur l'ESP32. Utilise-les pour une seule petite valeur comme un drapeau ou un compteur ; pour plusieurs valeurs qui doivent changer ensemble, utilise un mutex."},"memory-order":{"short":"Dit à quel point une lecture ou écriture atomique doit s'aligner strictement sur la mémoire autour d'elle.","simple":"« Release » revient à poster une lettre seulement une fois cachetée ; « acquire » à l'ouvrir avant de la lire. Ensemble, ils garantissent que le lecteur voit tout ce que l'auteur a préparé.","deep":"<code>relaxed</code> ne rend atomique que la valeur elle-même. Un store <code>release</code> associé à un load <code>acquire</code> rend tout ce qui a été écrit avant le store visible après le load, à travers les deux cœurs de l'ESP32. La valeur par défaut (<code>seq_cst</code>) est la plus stricte."},"std-mutex":{"short":"Un verrou qui ne laisse entrer qu'une seule tâche à la fois dans un morceau de code ou de données.","simple":"L'unique clé d'une salle de bain partagée : celui qui la tient entre, tous les autres attendent devant la porte.","deep":"Sur Arduino-ESP32, il repose sur un mutex FreeRTOS, donc une tâche qui attend dort au lieu de tourner à vide. Ne le verrouille jamais dans une interruption. Verrouille-le via <code>std::lock_guard</code> pour qu'il soit toujours déverrouillé, même sur un <code>return</code> anticipé."},"lock-guard":{"short":"Verrouille un mutex à sa création et le déverrouille automatiquement à la fin du bloc.","simple":"Une clé qui se rend toute seule : elle prend la clé de la salle de bain quand tu entres et la remet toute seule quand tu sors, quelle que soit ta sortie.","deep":"RAII : le constructeur appelle <code>lock()</code>, le destructeur appelle <code>unlock()</code> quand la variable sort de sa portée. Impossible alors d'oublier le déverrouillage sur un <code>return</code> anticipé. Garde le bloc court."},"decltype":{"short":"Demande au compilateur « quel est le type de cette expression ? » et utilise la réponse comme type.","simple":"« Donne-moi une boîte exactement comme celle-là. »","deep":"Évalué à la compilation ; l'expression n'est jamais exécutée. Utile dans les templates et pour nommer le type d'une lambda."},"static-assert":{"short":"Une vérification qui s'exécute pendant la compilation ; si elle échoue, la compilation s'arrête avec ton message.","simple":"Un contrôleur à l'usine : une pièce qui ne s'ajuste pas ne quitte jamais le bâtiment.","deep":"Ne coûte rien à l'exécution. Usage typique : vérifier qu'une struct packée a bien la taille en octets qu'attend un protocole, ou qu'un tableau a une entrée par valeur d'enum."},"mutable":{"short":"Laisse un membre changer même dans une fonction <code>const</code>, pour une comptabilité qui ne fait pas partie de la valeur de l'objet.","simple":"Un bloc-notes accroché à un document scellé : le document reste le même, les notes peuvent changer.","deep":"Typique pour un mutex ou un cache dans un objet dont les fonctions de lecture sont <code>const</code> : verrouiller change le mutex, mais pas ce que l'objet signifie. Sur une lambda, <code>mutable</code> lui permet de changer ses propres copies capturées."},"include":{"short":"Colle un autre fichier ici, pour que ce fichier puisse utiliser ce qu'il déclare.","simple":"Comme écrire « voir la fiche de recette jointe » en haut d'une recette : les ingrédients qu'elle liste sont maintenant disponibles.","deep":"<code>&lt;Arduino.h&gt;</code> entre chevrons cherche dans les chemins des bibliothèques et du système ; <code>\\"pins.h\\"</code> entre guillemets cherche d'abord à côté de ce fichier (et dans le <code>include/</code> du projet). C'est un simple collage de texte, fait avant la compilation."},"pragma-once":{"short":"Garantit qu'un fichier d'en-tête n'est collé qu'une seule fois, peu importe combien de fichiers l'incluent.","simple":"Un marque-page « tu as déjà lu ça » : la deuxième fois, la page est sautée.","deep":"Pris en charge par GCC et tous les grands compilateurs ; il remplace l'ancienne garde d'inclusion <code>#ifndef X / #define X / #endif</code>. Sans lui, une struct définie deux fois serait une erreur de compilation."},"define":{"short":"Crée un nom qui est remplacé par du texte avant la compilation du code.","simple":"Un chercher-remplacer fait par l'ordinateur juste avant de lire ton code : chaque <code>PIN_RGB</code> devient <code>48</code>.","deep":"Les macros ne savent rien des types ni de la portée. <code>pins.h</code> en utilise pour qu'une option de compilation comme <code>-DPIN_RGB=38</code> puisse remplacer une broche ; pour les constantes ordinaires, préfère <code>constexpr</code>. Une macro avec parenthèses, comme <code>BLE_NOTE(kind, ...)</code>, colle ses arguments."},"conditional-compile":{"short":"Garde ou retire des lignes de code avant la compilation, selon qu'un nom est défini ou non.","simple":"« Si personne n'a encore choisi de broche, utilise 48. » Les lignes qui ne s'appliquent pas sont coupées avant que le compilateur ne les voie.","deep":"<code>#ifndef PIN_RGB</code> ... <code>#endif</code> laisse les options de compilation de <code>platformio.ini</code> l'emporter sur les valeurs par défaut de <code>pins.h</code>. <code>#if</code> teste une expression constante ; chaque <code>#if</code>/<code>#ifdef</code>/<code>#ifndef</code> demande un <code>#endif</code> correspondant."},"serial-begin":{"short":"Ouvre la liaison série vers ton ordinateur à une vitesse choisie, pour que la carte puisse afficher des messages.","simple":"Décrocher le téléphone et se mettre d'accord sur la vitesse à laquelle vous parlerez tous les deux. 115200 est la vitesse d'écoute du moniteur série.","deep":"Vitesse en bauds (bits par seconde) ; elle doit correspondre à <code>monitor_speed</code> dans <code>platformio.ini</code>. Dans ces labos, <code>Serial</code> est l'UART0, atteint par la puce USB-série du port <code>COM</code>, donc rien n'a besoin d'attendre l'énumération USB."},"serial-printf":{"short":"Affiche une ligne dans le moniteur série, en remplissant les valeurs avec des codes <code>%</code>.","simple":"Une lettre type : <code>\\"%d cores\\"</code> a un blanc, et le nombre que tu passes le remplit.","deep":"Formate avec <code>vsnprintf</code> puis écrit sur l'UART0 à 115200 bauds (environ 11,5 KB/s, donc de longs affichages ralentissent une boucle). Codes : <code>%d</code> int, <code>%u</code> unsigned, <code>%lu</code> unsigned long, <code>%.1f</code> float, <code>%s</code> chaîne C (utilise <code>.c_str()</code> pour une <code>String</code>), <code>%02X</code> hexa sur deux chiffres. Ajoute <code>\\\\n</code> toi-même."},"serial-print":{"short":"Affiche du texte ou un nombre dans le moniteur série ; <code>println</code> passe aussi à la ligne.","simple":"Dire quelque chose à voix haute à ton ordinateur. <code>println</code> revient à appuyer sur Entrée ensuite.","deep":"Accepte du texte, des nombres et des <code>String</code> ; <code>Serial.print(x, HEX)</code> affiche en hexadécimal. Il écrit dans un tampon d'émission et n'attend que quand ce tampon est plein."},"serial-read":{"short":"<code>available()</code> dit combien de lettres tapées attendent ; <code>read()</code> prend la suivante.","simple":"Vérifier la boîte aux lettres : <code>available()</code> te dit combien de lettres s'y trouvent, <code>read()</code> en sort une.","deep":"Les deux reviennent immédiatement ; <code>read()</code> donne -1 quand rien n'attend. Les labos rassemblent les lettres dans un tampon jusqu'à un saut de ligne, puis exécutent la commande, donc taper ne bloque jamais l'écran. <code>flush()</code> attend que tout ce qui a été affiché soit parti."},"pin-mode":{"short":"Configure une broche GPIO en entrée ou en sortie avant de l'utiliser.","simple":"Décider si une porte sert à entrer (lire un bouton) ou à sortir (allumer une LED).","deep":"Configure la matrice GPIO pour cette broche. <code>INPUT_PULLUP</code> active aussi une faible résistance interne vers 3,3 V, donc un bouton vers GND n'a besoin d'aucune pièce en plus. Évite les broches de strapping, de flash et de PSRAM listées en haut de <code>pins.h</code>."},"pin-modes":{"short":"Les façons de configurer une broche : écouter, piloter, ou écouter avec une résistance intégrée.","simple":"<code>OUTPUT</code> est un robinet que tu ouvres et fermes. <code>INPUT</code> est un cadran que tu lis. <code>INPUT_PULLUP</code> est un cadran qui reste au niveau « haut » jusqu'à ce que quelque chose le tire vers le bas.","deep":"Un <code>INPUT</code> flottant capte du bruit ; <code>INPUT_PULLUP</code>/<code>INPUT_PULLDOWN</code> activent les faibles résistances internes de l'ESP32 (des dizaines de kilo-ohms). C'est pourquoi les boutons appuyés lisent <code>LOW</code> dans ces labos."},"digital-write":{"short":"Met une broche de sortie à l'état haut (3,3 V) ou bas (0 V).","simple":"Actionner un interrupteur : <code>HIGH</code> est allumé, <code>LOW</code> est éteint.","deep":"Les broches de l'ESP32-S3 sont en 3,3 V, jamais en 5 V. Chaque broche peut fournir ou absorber environ 20 mA par défaut (réglable avec <code>gpio_set_drive_capability</code>), donc une LED a toujours besoin d'une résistance en série."},"digital-read":{"short":"Lit si une broche d'entrée est à l'état haut (près de 3,3 V) ou bas (près de 0 V).","simple":"Demander à un bouton de sonnette : es-tu appuyé en ce moment ?","deep":"Renvoie <code>HIGH</code> (1) ou <code>LOW</code> (0). Avec <code>INPUT_PULLUP</code>, un bouton appuyé lit <code>LOW</code>, d'où <code>== LOW</code> pour dire « appuyé ». Les contacts mécaniques rebondissent pendant quelques ms, ce que <code>Button</code> filtre."},"high-low":{"short":"Les deux niveaux d'une broche numérique : <code>HIGH</code> vaut 3,3 V, <code>LOW</code> vaut 0 V.","simple":"Allumé et éteint, version tension.","deep":"Ce sont simplement 1 et 0. Sur l'ESP32, une entrée lit <code>HIGH</code> au-dessus d'environ trois quarts de 3,3 V et <code>LOW</code> sous un quart ; entre les deux, rien n'est garanti."},"analog-read":{"short":"Mesure la tension sur une broche sous forme d'un nombre de 0 à 4095.","simple":"Une lecture de variateur au lieu d'un interrupteur on/off : à quelle hauteur est la tension, sur une échelle de 0 à 4095 ?","deep":"Le CAN de l'ESP32-S3 fait 12 bits. Utilise les broches ADC1 (GPIO 1-10) : l'ADC2 est partagé avec le Wi-Fi. Un appel est un échantillon lent, c'est pourquoi les labos de son utilisent plutôt le mode continu du CAN avec DMA."},"millis":{"short":"Combien de millisecondes se sont écoulées depuis le démarrage de la carte.","simple":"Un chronomètre qui démarre à la mise sous tension et ne s'arrête jamais. Compare-le à une lecture précédente pour savoir combien de temps a passé.","deep":"Renvoie un <code>unsigned long</code> de 32 bits dérivé du <code>esp_timer</code> de 64 bits. Il repasse à 0 après environ 49,7 jours, et <code>millis() - last >= interval</code> reste correct à travers ce retour grâce au calcul non signé. C'est ainsi que les boucles font des choses « toutes les N ms » sans <code>delay()</code>."},"micros":{"short":"Combien de microsecondes (millionièmes de seconde) se sont écoulées depuis le démarrage de la carte.","simple":"Le même chronomètre que <code>millis()</code>, lu mille fois plus finement.","deep":"32 bits, donc il repasse à zéro après environ 71,6 minutes ; bien pour chronométrer de courtes choses, utilise <code>esp_timer_get_time()</code> pour une horloge de 64 bits qui ne boucle jamais en pratique."},"delay":{"short":"Met en pause le code courant pendant un certain nombre de millisecondes.","simple":"Faire une sieste : rien d'autre dans <code>loop()</code> ne se passe tant que tu ne te réveilles pas.","deep":"Sur l'ESP32, il appelle <code>vTaskDelay</code>, donc le CPU est libre pour d'autres tâches (Wi-Fi, BLE, l'échantillonneur) pendant que celle-ci dort. Le tick FreeRTOS est de 1 ms ici. De longs délais figent quand même les boutons et l'écran, donc les labos utilisent surtout des vérifications avec <code>millis()</code>."},"delay-microseconds":{"short":"Attend un tout petit nombre de microsecondes, pour du matériel qui demande des pauses très courtes.","simple":"Retenir son souffle le temps d'un clin d'œil : trop court pour une sieste, donc on attend sur place.","deep":"Une attente active : le CPU tourne à vide et les autres tâches de ce cœur ne s'exécutent pas. Correct pour quelques centaines de microsecondes (laisser se stabiliser une résistance de rappel), jamais pour de longues attentes."},"ledc-attach":{"short":"Transforme une broche en sortie PWM avec une fréquence et une résolution choisies, pour atténuer des LED ou des rétroéclairages.","simple":"Installer un interrupteur très rapide qui s'allume et s'éteint des milliers de fois par seconde, pour que l'œil voie « à moitié lumineux ».","deep":"API Arduino-ESP32 3.x sur le périphérique LEDC : <code>ledcAttach(pin, freq, bits)</code> renvoie <code>false</code> si aucun canal ou aucune fréquence ne convient. 5 kHz sur 8 bits donne des valeurs de rapport de 0 à 255 sans scintillement visible."},"ledc-write":{"short":"Règle la part de chaque cycle PWM où la broche reste à l'état haut : 0 est éteint, la valeur max est à fond.","simple":"Tourner le bouton du variateur sur cet interrupteur rapide.","deep":"Dans Arduino-ESP32 3.x, il prend la broche (la 2.x prenait un canal). La plage du rapport va de 0 à 2^bits - 1 (0-255 pour 8 bits) définie par <code>ledcAttach</code> ; le matériel LEDC entretient le signal sans aucun travail du CPU."},"rgb-led-write":{"short":"Règle la couleur de la LED RGB intégrée à la carte à partir de valeurs de rouge, de vert et de bleu (0-255 chacune).","simple":"Mélanger de la peinture : un peu de rouge, beaucoup de vert, pas de bleu. La LED montre le mélange.","deep":"La LED de la carte est une WS2812 qui reçoit la couleur sous forme d'un train d'impulsions chronométré avec précision ; Arduino-ESP32 le génère avec le périphérique RMT. Elle est très lumineuse, donc les labos réduisent les valeurs. S'appelait <code>neopixelWrite</code> dans les anciens cœurs."},"attach-interrupt":{"short":"Exécute une fonction à l'instant où une broche change, même quand le reste du code est occupé.","simple":"Une sonnette plutôt que de guetter par la fenêtre : la carte est interrompue dès que quelqu'un appuie.","deep":"<code>CHANGE</code>, <code>RISING</code> ou <code>FALLING</code> choisit quels fronts déclenchent. <code>attachInterruptArg</code> passe aussi un <code>void *</code> (ici <code>this</code>) pour qu'un gestionnaire static retrouve son objet. Les gestionnaires doivent être courts, marqués <code>IRAM_ATTR</code>, et ne toucher que des données <code>volatile</code> ou atomiques."},"digital-pin-to-interrupt":{"short":"Transforme un numéro de broche en numéro d'interruption attendu par <code>attachInterrupt</code>.","simple":"Chercher quel fil de sonnette appartient à quelle porte.","deep":"Sur l'ESP32, chaque GPIO peut interrompre et le numéro est la broche elle-même, mais l'écrire garde le code portable vers des cartes où ils diffèrent."},"random":{"short":"Choisit un nombre entier au hasard : <code>random(40, 200)</code> donne de 40 jusqu'à 199.","simple":"Lancer des dés dont tu choisis les faces. Le nombre du haut n'est jamais tiré.","deep":"<code>random(max)</code> donne 0 à max-1, <code>random(min, max)</code> de min à max-1. <code>randomSeed(esp_random())</code> démarre la séquence à partir d'un nombre aléatoire matériel, donc chaque démarrage est différent."},"constrain":{"short":"Garde une valeur entre une valeur minimale et une valeur maximale permises.","simple":"Les barrières d'une piste de bowling : la boule peut rouler où elle veut entre elles, jamais au-delà.","deep":"La version Arduino de <code>std::clamp</code> : <code>constrain(x, lo, hi)</code>. Les notes et vélocités MIDI doivent rester entre 0 et 127, donc le labo BLE MIDI les borne."},"min-max":{"short":"Le raccourci Arduino pour le plus petit ou le plus grand de deux valeurs.","simple":"« Le plus petit des deux » ou « le plus grand des deux ». <code>max(2, s / 6)</code> veut dire « au moins 2 ».","deep":"Donne aux deux arguments le même type pour éviter les surprises. Ailleurs, les labos écrivent <code>std::min</code>/<code>std::max</code>, qui acceptent aussi un type explicite : <code>std::min&lt;uint32_t&gt;(n, 320)</code>."},"string-c-str":{"short":"Donne le texte d'une <code>String</code> sous forme de chaîne C simple, pour les fonctions qui veulent un <code>const char *</code>.","simple":"Sortir les lettres de leur carnet extensible et les poser sur la table, pour quelqu'un qui ne lit que des tuiles.","deep":"Le pointeur n'est valide que tant que la <code>String</code> vit et n'est pas modifiée ; ne le garde jamais depuis un temporaire comme <code>a.toString().c_str()</code> au-delà de cette ligne. Nécessaire pour <code>%s</code> dans printf."},"string-is-empty":{"short":"Demande à une <code>String</code> si elle n'a aucune lettre, ou combien de lettres elle a.","simple":"La page du carnet est-elle blanche ? Combien de lettres y a-t-il dessus ?","deep":"<code>length()</code> compte les caractères (des octets, donc un emoji compte pour plusieurs) et n'inclut pas le <code>'\\\\0'</code> caché. <code>isEmpty()</code> équivaut à <code>length() == 0</code> et se lit mieux."},"string-substring":{"short":"<code>indexOf</code> trouve où un texte apparaît ; <code>substring</code> en découpe un morceau.","simple":"Trouver un mot dans une phrase avec le doigt, puis découper avec des ciseaux la partie dont tu as besoin.","deep":"Les positions comptent à partir de 0. <code>substring(from)</code> va jusqu'à la fin, <code>substring(from, to)</code> s'arrête juste avant <code>to</code>. <code>indexOf</code> renvoie -1 quand rien n'est trouvé. Chaque <code>substring</code> crée une nouvelle <code>String</code> dans le tas."},"string-starts-with":{"short":"Vérifie si une <code>String</code> commence (ou finit) par un certain texte.","simple":"« Cette commande commence-t-elle par 'vol ' ? » Un oui ou un non rapide.","deep":"Sensible à la casse, c'est pourquoi les commandes sont d'abord mises en minuscules (<code>lower.startsWith(...)</code>). C'est ainsi que l'analyseur de commandes série de chaque labo reconnaît ses mots."},"string-trim":{"short":"Nettoie un texte sur place : retire les espaces aux extrémités, change la casse, ou remplace un morceau de texte par un autre.","simple":"Redresser un mot avant de le lire : pas d'espaces en trop, tout en minuscules, pour que « Help » et « help » veuillent dire la même chose.","deep":"Elles modifient la <code>String</code> elle-même et ne renvoient rien, donc appelle-les sur une copie qui t'appartient : <code>String lower = line; lower.toLowerCase();</code>. <code>trim</code> retire aussi le <code>\\\\r</code> que certains terminaux envoient."},"string-to-int":{"short":"Transforme un texte comme <code>\\"42\\"</code> en le nombre 42.","simple":"Lire les chiffres d'un mot et les taper dans une calculatrice.","deep":"Renvoie un <code>long</code> (ou un <code>float</code>). Un texte qui ne commence pas par un nombre donne 0, donc un <code>0</code> tapé et du charabia se ressemblent ; vérifie le texte quand ça compte."},"spi-begin":{"short":"Démarre le bus SPI sur les broches de ton choix, pour que la carte puisse parler vite à l'écran ou au lecteur RFID.","simple":"Tirer une ligne téléphonique privée avec des fils séparés pour parler, écouter et le rythme sur lequel les deux côtés se calent.","deep":"<code>SPI.begin(sck, miso, mosi, ss)</code> ; -1 saute une broche (l'écran n'a pas de MISO). <code>SPI</code> est le SPI2 (FSPI) du S3 ; le parcours RFID construit un second <code>SPIClass</code> sur SPI3 pour que les deux ne partagent jamais fils ni timing."},"log-macros":{"short":"Affichent une ligne de journal étiquetée : <code>i</code> info, <code>w</code> avertissement, <code>e</code> erreur, <code>d</code> debug.","simple":"Des notes dans le journal de bord d'un navire, chacune avec un tampon indiquant sa gravité.","deep":"Des macros Arduino-ESP32 avec des modèles à la printf. Chaque ligne est préfixée du niveau, du fichier, de la ligne et de la fonction, et les lignes au-dessus de <code>CORE_DEBUG_LEVEL</code> (3 = info dans <code>platformio.ini</code>) sont retirées à la compilation, donc <code>log_d</code> ne coûte rien ici. La sortie va sur le même port série que <code>Serial</code>."},"esp-info":{"short":"Demande à la puce de parler d'elle-même : modèle, cœurs, vitesse, taille de flash et de PSRAM, adresse MAC.","simple":"La carte qui lit sa propre carte d'identité à voix haute.","deep":"La leçon 01 attend <i>ESP32-S3</i>, 2 cœurs à 240 MHz, 16 MB de flash (le N16) et environ 8 MB de PSRAM (le R8). <code>getEfuseMac()</code> renvoie la MAC d'usine depuis l'eFuse en <code>uint64_t</code>, octet de poids faible en premier."},"free-heap":{"short":"Combien de mémoire est encore libre pour de nouvelles allocations.","simple":"Vérifier combien de place il reste dans le placard avant d'acheter plus.","deep":"<code>ESP.getFreeHeap()</code> compte la RAM interne ; <code>heap_caps_get_free_size(MALLOC_CAP_SPIRAM)</code> compte la PSRAM. Libre n'est pas la même chose qu'utilisable : <code>heap_caps_get_largest_free_block</code> donne le plus gros morceau d'un seul tenant, ce dont a besoin un tampon d'image."},"esp-restart":{"short":"Redémarre la puce de zéro, comme si tu avais appuyé sur le bouton reset.","simple":"L'éteindre et la rallumer, depuis l'intérieur du programme.","deep":"Un reset logiciel : la RAM est effacée, la NVS (Preferences) survit, et <code>esp_reset_reason()</code> indiquera <code>ESP_RST_SW</code> la fois suivante. Utilisé après avoir changé un réglage enregistré qui ne s'applique qu'au démarrage."},"esp-reset-reason":{"short":"Te dit pourquoi la carte a démarré la dernière fois : mise sous tension, bouton reset, plantage, chute de tension...","simple":"Se réveiller et demander « me suis-je juste endormi, ou suis-je tombé ? »","deep":"Renvoie un <code>esp_reset_reason_t</code> comme <code>ESP_RST_POWERON</code>, <code>ESP_RST_SW</code>, <code>ESP_RST_PANIC</code>, <code>ESP_RST_TASK_WDT</code> ou <code>ESP_RST_BROWNOUT</code> (la tension d'alimentation a chuté). L'afficher au démarrage rend les plantages visibles."},"esp-timer-get-time":{"short":"Microsecondes depuis le démarrage, d'une horloge de 64 bits qui ne s'épuise jamais.","simple":"Un chronomètre très précis : bien pour mesurer combien de temps a pris le dessin d'une image d'écran.","deep":"Renvoie un <code>int64_t</code> du minuteur haute résolution d'ESP-IDF ; peut être appelé depuis une interruption. <code>millis()</code> et <code>micros()</code> sont construits dessus. Le gestionnaire de bouton ne garde que les 32 bits de poids faible pour qu'une lecture soit une seule étape."},"esp-timer":{"short":"Met en place un callback qu'ESP-IDF exécute après un délai ou sur un rythme régulier, avec un timing à la microseconde.","simple":"Un minuteur de cuisine qui sonne toutes les 125 ms, quoi que fasse le reste du code.","deep":"Les callbacks s'exécutent dans la tâche <code>esp_timer</code> de haute priorité, pas dans <code>loop()</code>, donc garde-les courts et partage les données en sécurité. Les périodes sont en microsecondes."},"esp-random":{"short":"Un nombre aléatoire de 32 bits issu du générateur de nombres aléatoires matériel de la puce.","simple":"Des dés lancés par la physique à l'intérieur de la puce plutôt que par une formule.","deep":"Vraiment aléatoire tant que le Wi-Fi ou le Bluetooth fonctionne (le bruit radio l'alimente) ; avant cela, considère-le comme seulement pseudo-aléatoire. <code>esp_fill_random(buf, n)</code> remplit un tampon, comme le fait le labo du coffre-fort pour sa clé secrète."},"heap-caps-malloc":{"short":"Demande un bloc de mémoire dans un type de RAM choisi : interne rapide ou PSRAM externe plus grande.","simple":"Choisir entre le petit tiroir de ton bureau (rapide d'accès) et le grand débarras au bout du couloir (spacieux mais plus lent).","deep":"Le S3 a environ 512 KB de SRAM interne et ici 8 MB de PSRAM octale. <code>MALLOC_CAP_INTERNAL</code> ou <code>MALLOC_CAP_SPIRAM</code> choisit le réservoir ; le résultat est <code>nullptr</code> si aucun bloc n'est assez grand. Libère-le avec <code>heap_caps_free</code>."},"gpio-drive":{"short":"Choisit avec quelle force une broche de sortie pousse du courant, de faible à forte.","simple":"Régler avec quelle force un robinet peut pousser l'eau : un filet doux ou la pleine pression.","deep":"Un appel ESP-IDF (il demande un <code>gpio_num_t</code>, d'où le cast). Les niveaux 0-3 valent à peu près 5, 10, 20 (par défaut) et 40 mA. Une sortie plus faible rend les fronts plus doux et garde les LED moins lumineuses."},"esp-err":{"short":"Les fonctions ESP-IDF répondent par un code de résultat ; <code>ESP_OK</code> (0) veut dire que ça a marché.","simple":"Un reçu : « OK », ou la raison pour laquelle non.","deep":"Toute autre valeur est une erreur comme <code>ESP_ERR_NO_MEM</code> ou <code>ESP_ERR_TIMEOUT</code> ; <code>esp_err_to_name()</code> la transforme en texte pour le journal. Les labos vérifient <code>!= ESP_OK</code> et abandonnent au lieu de planter."},"preferences":{"short":"Enregistre de petits réglages dans la flash de la puce pour qu'ils survivent à l'extinction et au reflashage.","simple":"Un carnet collé à l'intérieur de la carte : écris « nom du Wi-Fi = maison » et il y est encore demain.","deep":"L'enveloppe d'Arduino autour de la NVS d'ESP-IDF, un stockage clé-valeur dans sa propre partition flash. <code>begin(\\"ns\\", readOnly)</code> ouvre un namespace ; les namespaces et les clés font au plus 15 caractères. Non chiffré par défaut ; appelle <code>end()</code> quand tu as fini."},"preferences-put-get":{"short":"Écrire une valeur sous une clé, ou la relire avec une valeur de repli si elle n'a jamais été enregistrée.","simple":"Des bocaux étiquetés sur une étagère : mets quelque chose dans le bocal « vol », et reprends-le plus tard.","deep":"Le type est dans le nom (<code>UChar</code> = <code>uint8_t</code>, <code>UInt</code> = <code>uint32_t</code>). <code>getX(key, fallback)</code> renvoie la valeur de repli quand la clé manque. Les écritures usent la flash, donc les labos n'enregistrent qu'en cas de changement."},"x-task-create":{"short":"Démarre une nouvelle tâche : une fonction qui s'exécute en parallèle de <code>loop()</code>, sur un cœur de ton choix.","simple":"Embaucher un deuxième cuisinier. Il a sa propre recette et travaille en même temps que toi, sur son propre fourneau.","deep":"Arguments : fonction, nom, taille de pile, paramètre <code>void *</code> (souvent <code>this</code>), priorité, un handle facultatif, cœur. Dans ESP-IDF, la taille de pile est en <b>octets</b>. <code>loop()</code> tourne sur le cœur 1 ; les labos épinglent leurs lecteurs et échantillonneurs au cœur 0. Renvoie <code>pdPASS</code> en cas de succès."},"v-task-delay":{"short":"Endort cette tâche pendant un certain nombre de ticks, pour que les autres tâches aient le CPU.","simple":"Le deuxième cuisinier qui s'écarte un instant du fourneau pour qu'un autre puisse l'utiliser.","deep":"Les ticks font 1 ms sur Arduino-ESP32, mais écris <code>pdMS_TO_TICKS(ms)</code> pour que le sens soit clair. La boucle sans fin d'une tâche doit bloquer ou temporiser quelque part, sinon les tâches de priorité plus basse sont affamées et le watchdog se plaint."},"pd-ms-to-ticks":{"short":"Convertit des millisecondes en ticks FreeRTOS, l'unité de toute attente dans FreeRTOS.","simple":"Traduire des minutes dans les unités propres de l'horloge de la cuisine.","deep":"Une macro : <code>ms * configTICK_RATE_HZ / 1000</code>. Avec le tick de 1000 Hz d'ici, c'est un pour un, mais le code reste juste si la fréquence du tick change. Les attentes plus courtes qu'un tick sont arrondies à 0."},"port-max-delay":{"short":"« Attends pour toujours » : passe-le comme délai pour bloquer jusqu'à ce que quelque chose arrive.","simple":"Rester près de la boîte aux lettres jusqu'à ce que le courrier arrive, le temps que ça prenne.","deep":"Le plus grand nombre de ticks, que FreeRTOS traite comme une absence de délai. Bien pour une tâche de travail qui n'a rien d'autre à faire ; ne l'utilise jamais dans <code>loop()</code> ni dans une interruption."},"pd-true":{"short":"Les propres réponses oui/non de FreeRTOS : <code>pdTRUE</code>/<code>pdPASS</code> veulent dire que ça a marché.","simple":"Le reçu que FreeRTOS rend après une requête sur une file ou une tâche.","deep":"De simples entiers (<code>BaseType_t</code>), 1 pour vrai/réussi et 0 pour faux/échec. Compare-les explicitement : <code>xQueueSend(...) == pdTRUE</code>."},"x-queue-create":{"short":"Crée une file : une boîte aux lettres sûre pour passer des éléments d'une tâche à une autre.","simple":"Une boîte aux lettres avec un nombre fixe de fentes : une tâche y dépose des lettres, une autre les retire, et elles ne se heurtent jamais.","deep":"<code>xQueueCreate(length, itemSize)</code> renvoie un <code>QueueHandle_t</code>, ou null s'il n'y a plus de mémoire. Les éléments sont <b>copiés</b> à l'entrée et à la sortie, donc envoie de petites structs, pas des pointeurs vers des choses qui pourraient disparaître."},"x-queue-send":{"short":"Met une copie d'un élément dans une file, en attendant jusqu'à un délai maximal si elle est pleine.","simple":"Déposer une lettre dans la boîte aux lettres. Si la boîte est pleine, tu peux attendre un instant, ou partir.","deep":"Un délai de 0 ne bloque jamais et renvoie <code>errQUEUE_FULL</code> quand il n'y a pas de place : adapté à <code>loop()</code> et aux gestionnaires web, qui ne doivent pas se bloquer. Depuis une interruption, utilise la version <code>FromISR</code>."},"x-queue-receive":{"short":"Retire l'élément suivant d'une file, en attendant jusqu'à un délai maximal si elle est vide.","simple":"Ouvrir la boîte aux lettres : prends la plus ancienne lettre, ou attends un peu qu'une arrive.","deep":"Les éléments sortent dans l'ordre, copiés dans ta variable. Une tâche de travail se bloque typiquement ici avec un délai (ou <code>portMAX_DELAY</code>), sans utiliser de CPU jusqu'à l'arrivée du travail."},"semaphore":{"short":"Un signal qu'une tâche attend et qu'une autre (ou une interruption) donne.","simple":"Un témoin dans une course de relais : le coureur attend que le témoin lui soit passé, puis il part.","deep":"Le pilote MFRC522 dort dans <code>xSemaphoreTake(done_, timeout)</code> jusqu'à ce que l'interruption IRQ du lecteur appelle <code>xSemaphoreGiveFromISR</code>, donc aucune scrutation SPI n'est nécessaire. Un sémaphore mutex ajoute l'héritage de priorité pour le verrouillage."},"task-handle":{"short":"Un handle désigne une tâche en cours ; <code>vTaskDelete</code> en termine une.","simple":"Le badge nominatif du deuxième cuisinier, et le mot qui le renvoie chez lui.","deep":"<code>vTaskDelete(nullptr)</code> termine la tâche appelante ; une fonction de tâche ne doit jamais simplement retourner. <code>uxTaskGetStackHighWaterMark</code> montre à quel point une tâche a frôlé le débordement de sa pile."},"critical-section":{"short":"Verrouille quelques lignes pour qu'aucune autre tâche, aucun autre cœur ni aucune interruption ne touche aux mêmes données entre-temps.","simple":"Tenir la porte fermée avec le pied une seconde pendant que tu échanges deux objets sur l'étagère.","deep":"Prend un spinlock <code>portMUX_TYPE</code> et désactive les interruptions sur ce cœur, donc il marche à travers les deux cœurs de l'ESP32 et avec les interruptions. Garde la section à quelques copies : pas d'affichage, pas d'attente, pas d'allocation."},"adafruit-st7789":{"short":"Le pilote de l'écran couleur de 1,9 pouce en 320×170 utilisé à partir de la leçon 03.","simple":"L'interprète entre la carte et l'écran : tu dis « dessine ça », il parle la langue de l'écran en SPI.","deep":"Le pilote ST7789 d'Adafruit. <code>init(170, 320)</code> règle la taille de la dalle, <code>setRotation(1)</code> la met en paysage, <code>setSPISpeed</code> monte l'horloge à 40 MHz. Les pixels sont en RGB565."},"adafruit-gfx":{"short":"La bibliothèque de dessin derrière chaque appel d'écran : lignes, cercles, rectangles, texte.","simple":"Une boîte de pochoirs et de stylos. Tout écran capable de colorier un pixel obtient gratuitement toutes les autres formes.","deep":"Une classe de base abstraite : une sous-classe n'a qu'à implémenter <code>drawPixel</code>, et tout le reste est construit dessus (notre <code>FrameBuffer</code> redéfinit aussi les appels de ligne et de remplissage pour la vitesse). Les coordonnées sont des <code>int16_t</code>, depuis le coin en haut à gauche."},"gfx-canvas16":{"short":"Une image hors écran en mémoire sur laquelle tu dessines, puis que tu envoies à l'écran d'un coup.","simple":"Esquisser d'abord sur papier puis tenir la page terminée devant la fenêtre, pour que personne ne voie un dessin à moitié fait.","deep":"La toile 16 bits d'Adafruit GFX : un <code>uint16_t</code> par pixel, 320×170×2 = environ 106 KB. Elle alloue avec un simple <code>malloc</code>, qui atterrit ici en PSRAM ; notre <code>FrameBuffer</code> préfère plutôt la RAM interne."},"frame-buffer":{"short":"L'image hors écran de ce projet : dessine dedans avec les appels GFX habituels, puis pousse-la vers l'écran.","simple":"Notre propre bloc d'esquisse, gardé dans le tiroir le plus rapide qui a de la place.","deep":"Défini dans <code>kit/lib/bench/src/frame_buffer.h</code>. <code>begin()</code> essaie d'abord la RAM interne rapide et se replie sur la PSRAM, et <code>internal()</code> dit laquelle il a obtenue. Il redéfinit <code>drawPixel</code>, <code>fillScreen</code> et les appels de ligne et de rectangle avec des écritures directes dans <code>pixels()</code>."},"display":{"short":"L'aide d'écran de ce projet : le ST7789, son rétroéclairage et le tampon d'image, configurés de la même façon dans chaque labo.","simple":"L'écran et son bloc d'esquisse emballés ensemble : dessine sur <code>fb()</code>, puis <code>push()</code> l'affiche.","deep":"Défini dans <code>kit/lib/bench/src/display.h</code>. <code>begin()</code> démarre le PWM du rétroéclairage, le SPI à 40 MHz et la dalle en paysage ; <code>push()</code> envoie toute l'image avec un seul <code>drawRGBBitmap</code>."},"button":{"short":"L'aide pour bouton poussoir de ce projet : transforme les appuis bruts en clics, doubles-clics et appuis longs propres.","simple":"Un portier pour le bouton : il ignore le tremblement des contacts métalliques et te dit ce que la personne voulait vraiment.","deep":"Défini dans <code>kit/lib/bench/src/button.h</code>. Une interruption <code>IRAM_ATTR</code> compte chaque front ; <code>poll()</code> accepte un nouveau niveau après 25 ms de calme et signale <code>Event::Click</code>, <code>DoubleClick</code> (en moins de 280 ms) ou <code>LongPress</code> (600 ms)."},"lab-shell":{"short":"La coque partagée sur laquelle sont construits les labos de chaque parcours : écran, bouton, LED, commandes série et crochets.","simple":"Un établi tout fait. Chaque labo n'apporte que ses propres outils (vues et commandes) et les branche dessus.","deep":"Un labo est un <code>...Spec</code> : ses vues (fonctions de dessin plus une action de double-clic), ses commandes série et des crochets comme <code>setup</code>, <code>tick</code> et <code>gesture</code>. <code>lab.warn</code> et <code>lab.note</code> affichent des messages à la printf dans le journal et sur l'écran. Chaque <code>src/&lt;lab&gt;/main.cpp</code> est surtout cette liste, donc <code>help</code> montre exactement ce qu'enseigne la leçon."},"mfrc522":{"short":"Le pilote maison de ce projet pour le lecteur de cartes RC522, écrit registre par registre sans bibliothèque.","simple":"Parler directement à la puce du lecteur, un octet à la fois, pour que tu voies chaque mot de la conversation.","deep":"Défini dans <code>kit/lib/rfid-kit/src/mfrc522.h</code> : trames SPI, registres, FIFO, minuteur de la puce et soit scrutation, soit sommeil sur son fil IRQ. <code>iso14443a.h</code> et <code>mifare_classic.h</code> construisent le protocole de carte par-dessus."},"rgb565":{"short":"Transforme du rouge, du vert et du bleu (ou une teinte de la roue des couleurs) en une couleur d'écran de 16 bits.","simple":"Mélanger de la peinture, puis écrire le mélange comme un seul code que l'écran comprend.","deep":"RGB565 garde 5 bits de rouge, 6 de vert et 5 de bleu : <code>((r &amp; 0xF8) &lt;&lt; 8) | ((g &amp; 0xFC) &lt;&lt; 3) | (b &gt;&gt; 3)</code>. Notre <code>rgb()</code> est <code>constexpr</code>, donc les couleurs de la palette ne coûtent rien à l'exécution."},"gfx-fill-screen":{"short":"Peint tout l'écran (ou la toile) d'une seule couleur.","simple":"Une nouvelle couche de peinture sur tout, généralement la première étape pour dessiner une nouvelle image.","deep":"Sur notre <code>FrameBuffer</code>, c'est un seul <code>std::fill_n</code> sur 54 400 pixels ; sur la dalle elle-même, ça envoie autant de pixels par SPI."},"gfx-draw-pixel":{"short":"Colorie un seul point en x, y.","simple":"Un point de feutre.","deep":"La seule fonction que chaque surface Adafruit GFX doit fournir ; toutes les autres formes peuvent être faites à partir d'elle. La nôtre vérifie les limites et écrit <code>buf_[y * _width + x]</code>."},"gfx-rect":{"short":"Dessine un rectangle à partir de son coin supérieur gauche, sa largeur et sa hauteur : plein, en contour, ou avec des coins arrondis.","simple":"Tamponner une forme de boîte sur l'image.","deep":"Arguments : <code>(x, y, w, h, colour)</code>, plus un rayon de coin pour les versions arrondies. <code>fill</code> peint l'intérieur, <code>draw</code> seulement le contour. Les barres, panneaux et boutons de chaque écran de labo sont faits de ça."},"gfx-circle":{"short":"Dessine des formes rondes et des triangles : des cercles à partir d'un centre et d'un rayon, des triangles à partir de trois coins.","simple":"Un compas et une équerre pour l'écran.","deep":"<code>fillCircle(cx, cy, r, colour)</code> utilise le centre, pas un coin. Les triangles prennent <code>(x0, y0, x1, y1, x2, y2, colour)</code>. Le tout est construit à partir de lignes horizontales rapides sur notre tampon d'image."},"gfx-line":{"short":"Dessine une ligne droite entre deux points, ou une ligne horizontale ou verticale rapide.","simple":"Une règle et un crayon. Les lignes « rapides » ne vont qu'à l'horizontale ou à la verticale, et sont bien plus rapides.","deep":"<code>drawLine(x0, y0, x1, y1, c)</code> utilise l'algorithme de Bresenham, un pixel à la fois. <code>drawFastHLine(x, y, w, c)</code> remplit une suite de pixels avec un seul <code>std::fill_n</code> sur notre tampon d'image, donc les séparateurs et les barres l'utilisent."},"gfx-cursor":{"short":"<code>setCursor</code> règle où le texte commence ; <code>fb.print</code> écrit ensuite du texte à cet endroit sur l'écran.","simple":"Poser le stylo à un endroit avant d'écrire.","deep":"Avec la police intégrée, le point est le coin supérieur gauche du texte ; avec une <code>GFXfont</code> personnalisée, c'est l'extrémité gauche de la ligne de base, donc y doit être plus bas. <code>print</code> et <code>printf</code> (mêmes codes <code>%</code> que <code>Serial.printf</code>) font avancer le curseur au fil de l'écriture."},"gfx-text-style":{"short":"Choisis la couleur, la taille et la police du texte que tu affiches ensuite.","simple":"Choisir quel stylo et quel pochoir de lettres utiliser.","deep":"<code>setTextColor(fg)</code> dessine du texte transparent ; <code>setTextColor(fg, bg)</code> peint aussi le fond (police intégrée seulement). <code>setFont(&amp;FreeSans9pt7b)</code> choisit une police lisse fournie avec Adafruit GFX (9 pt, normale) ; <code>setFont(nullptr)</code> revient à la police intégrée 6×8 ; <code>setTextSize(2)</code> la double."},"gfx-text-bounds":{"short":"Mesure la largeur et la hauteur qu'aurait un texte, sans le dessiner.","simple":"Mesurer une enseigne avant de l'accrocher, pour pouvoir la centrer sur le mur.","deep":"<code>getTextBounds(text, x, y, &amp;x1, &amp;y1, &amp;w, &amp;h)</code> remplit la boîte que couvrirait le texte avec la police et la taille actuelles ; sert à centrer et à aligner à droite des étiquettes."},"gfx-rgb-bitmap":{"short":"Copie tout un bloc de pixels sur l'écran d'un coup.","simple":"Glisser une photo terminée dans le cadre, au lieu de la peindre point par point.","deep":"<code>drawRGBBitmap(x, y, pixels, w, h)</code> envoie des données RGB565 par SPI ; une image complète de 320×170 fait environ 106 KB, soit à peu près 22 ms à 40 MHz. C'est la limite supérieure de la fréquence d'images, c'est pourquoi les labos dessinent d'abord hors écran."},"gfx-rotation":{"short":"Tourne l'image de l'écran par pas de 90°, pour qu'elle se lise dans le bon sens.","simple":"Faire passer un cadre photo du format portrait au format paysage.","deep":"0-3 valent 0°, 90°, 180°, 270°. La rotation 1 fait de la dalle 170×320 un écran paysage de 320×170 ; largeur et hauteur s'échangent en conséquence."},"wifi-begin":{"short":"Commence à rejoindre un réseau Wi-Fi avec son nom et son mot de passe.","simple":"Frapper à la porte du routeur avec le mot de passe ; la réponse arrive quelques secondes plus tard.","deep":"Revient tout de suite ; la connexion se fait dans la tâche Wi-Fi en arrière-plan. Notre classe <code>Connection</code> écoute les événements (connecté, IP obtenue, déconnecté) au lieu d'attendre dans une boucle. Passer <code>nullptr</code> comme mot de passe rejoint un réseau ouvert."},"wifi-mode":{"short":"Choisit si la carte rejoint un réseau (station), crée le sien (point d'accès), ou les deux.","simple":"Être invité à la fête de quelqu'un d'autre, organiser la tienne, ou faire les deux à la fois.","deep":"<code>WIFI_AP_STA</code> fait tourner les deux sur une seule radio, donc ils partagent un canal ; le portail de configuration s'en sert pour afficher une page pendant qu'il essaie ton réseau. <code>softAP</code> démarre le réseau propre à la carte, joignable par défaut à <code>192.168.4.1</code>."},"wifi-info":{"short":"Demande à la connexion Wi-Fi des détails : l'adresse IP de la carte, la force du signal, le canal, la MAC.","simple":"Lire le numéro de la carte dans la rue du réseau, et combien de barres de signal elle a.","deep":"<code>localIP()</code> est une <code>IPAddress</code> (<code>toString()</code> pour du texte). <code>RSSI()</code> est en dBm : environ -50 est excellent, sous -80 est faible. Tout vaut 0 ou vide tant qu'on n'est pas connecté."},"wifi-scan":{"short":"Écoute les réseaux Wi-Fi proches et liste leurs noms, leur signal et leur sécurité.","simple":"Tourner le cadran de la radio pour entendre quelles stations sont dans les parages.","deep":"Avec <code>async = true</code>, il revient tout de suite (-1, toujours en cours) ; interroge <code>scanComplete()</code> pour le nombre, lis chaque entrée, puis <code>scanDelete()</code> pour libérer la liste. Un scan prend quelques secondes sur tous les canaux."},"wifi-events":{"short":"Enregistre une fonction que le pilote Wi-Fi appelle quand quelque chose arrive : connecté, IP obtenue, déconnecté.","simple":"Demander à la réceptionniste de t'appeler quand ton visiteur arrive, au lieu d'attendre dans le hall.","deep":"Le callback s'exécute dans la tâche d'événements Wi-Fi, pas dans <code>loop()</code>, donc il ne doit que poser des drapeaux ; <code>loop()</code> fait le vrai travail. <code>info</code> porte des détails comme la raison de la déconnexion."},"mdns":{"short":"Donne à la carte un nom sympa comme <code>bench.local</code> sur ton réseau.","simple":"Une étiquette de nom, pour que les autres appareils trouvent la carte sans connaître son numéro.","deep":"Le DNS multicast répond aux requêtes de noms sur le réseau local seulement ; macOS et iOS le gèrent d'office. <code>addService(\\"http\\", \\"tcp\\", 80)</code> annonce aussi le serveur web."},"ntp-time":{"short":"Règle l'horloge à partir de serveurs de temps d'internet, puis lit la date et l'heure locales.","simple":"La carte n'a pas d'horloge sur pile, donc elle demande à internet « quelle heure est-il ? » dès qu'elle est en ligne.","deep":"<code>configTzTime(tz, server1, server2)</code> règle le fuseau horaire POSIX et démarre SNTP. <code>getLocalTime(&amp;tm, timeoutMs)</code> remplit une <code>struct tm</code> et renvoie <code>false</code> tant que la première synchronisation n'a pas eu lieu."},"http-client":{"short":"Fait des requêtes web depuis la carte, comme un minuscule navigateur : demande une URL, récupère la réponse.","simple":"Envoyer une lettre à un site web et attendre sa réponse.","deep":"Le client HTTP d'Arduino-ESP32 sur une connexion TCP ou TLS. Notre <code>https::get</code> vérifie le certificat du serveur par rapport aux racines Mozilla incluses. Il bloque de 0,3 s à plusieurs secondes, donc appelle-le depuis une tâche de travail, jamais depuis <code>loop()</code>."},"json-document":{"short":"Le conteneur d'ArduinoJson pour les données JSON : remplis-le comme un dictionnaire, ou lis-en un reçu.","simple":"Un bac de classement avec des dossiers étiquetés : <code>doc[\\"heap\\"] = 1234</code> met un nombre dans le dossier appelé heap.","deep":"ArduinoJson 7 : un <code>JsonDocument</code> grandit dans le tas selon les besoins. <code>doc[\\"k\\"].to&lt;JsonArray&gt;()</code> crée des tableaux imbriqués ; <code>doc[\\"k\\"] | fallback</code> lit avec une valeur par défaut si la clé manque ou n'a pas le bon type."},"serialize-json":{"short":"Transforme un <code>JsonDocument</code> en texte JSON, prêt à envoyer.","simple":"Taper le contenu du bac de classement en une seule lettre bien rangée.","deep":"<code>serializeJson(doc, out)</code> écrit dans une <code>String</code>, un tampon <code>char</code> ou un flux comme <code>Serial</code>, et renvoie le nombre d'octets écrits."},"deserialize-json":{"short":"Lit du texte JSON dans un <code>JsonDocument</code> où tu peux chercher des choses.","simple":"Ouvrir une lettre et ranger son contenu dans les dossiers étiquetés.","deep":"Renvoie une <code>DeserializationError</code> qui est vraie quand quelque chose s'est mal passé (<code>e.c_str()</code> dit quoi). Un <code>Filter</code> ne garde que les champs dont tu as besoin, ce qui économise beaucoup de RAM sur les grosses réponses météo."},"async-web-server":{"short":"Un serveur web sur la carte : ton téléphone ou ton portable ouvre une page ou une API, et la carte répond.","simple":"Une petite vitrine de boutique : chaque adresse (<code>/api/card</code>) a un vendeur qui sait quoi répondre.","deep":"ESPAsyncWebServer répond dans sa propre tâche réseau, donc l'écran et le lecteur n'attendent jamais. <code>server_.on(path, HTTP_GET, handler)</code> enregistre une route ; les gestionnaires doivent être rapides et ne pas bloquer, donc le travail lourd est mis en file vers une autre tâche."},"async-request":{"short":"Une requête web entrante : ce qui a été demandé, et comment y répondre.","simple":"Le client à la vitrine : tu lis sa commande et tu lui rends une réponse.","deep":"Les gestionnaires la reçoivent sous forme de pointeur, d'où <code>req-&gt;send(200, \\"application/json\\", body)</code>. <code>hasParam</code>/<code>getParam</code> lisent les champs de requête ou de formulaire. Chaque requête doit recevoir exactement un <code>send</code>."},"async-web-socket":{"short":"Une ligne directe à double sens vers le navigateur, pour que la carte puisse pousser des mises à jour dès que quelque chose arrive.","simple":"Un appel téléphonique plutôt que des lettres : la ligne reste ouverte et chacun peut parler à tout moment.","deep":"Monté sur le serveur web à un chemin comme <code>/ws</code>. <code>textAll</code> envoie à tous les navigateurs connectés ; <code>onEvent</code> entend les connexions, déconnexions et messages. Appelle <code>cleanupClients()</code> de temps en temps pour abandonner les connexions parties."},"nimble-device":{"short":"La porte d'entrée du Bluetooth LE : démarre la pile radio et fournit serveurs, scanners et clients.","simple":"L'accueil du Bluetooth : dis bonjour une fois avec <code>init</code>, puis demande-lui ce dont tu as besoin.","deep":"NimBLE-Arduino, une pile BLE plus légère que Bluedroid. Ses fonctions sont <code>static</code>, donc on les appelle <code>NimBLEDevice::...</code> sans objet. <code>init(name)</code> règle le nom annoncé ; <code>setPower</code> règle la puissance d'émission en dBm."},"nimble-server":{"short":"Le propre menu Bluetooth de la carte : des services regroupent des caractéristiques, de petites valeurs qu'un téléphone peut lire, écrire ou auxquelles il peut s'abonner.","simple":"Un panneau d'affichage avec des cases étiquetées : un téléphone s'approche, lit la case température, ou épingle un message dans la case message.","deep":"GATT : un service (un UUID) contient des caractéristiques, chacune avec un UUID, des propriétés comme <code>READ | WRITE | NOTIFY</code> et une valeur jusqu'au MTU. <code>notify()</code> pousse une nouvelle valeur aux téléphones abonnés sans qu'on le demande."},"nimble-advertising":{"short":"Fait crier à la carte « Je suis là ! » plusieurs fois par seconde, pour que les téléphones puissent la voir et s'y connecter.","simple":"Un phare : de brefs éclats à intervalles réguliers que tous ceux qui sont proches peuvent repérer.","deep":"Un paquet d'annonce classique porte au plus 31 octets (nom, drapeaux, UUID de services, données du fabricant), plus 31 autres dans une réponse de scan."},"nimble-scan":{"short":"Écoute les autres appareils Bluetooth qui s'annoncent à proximité et signale chacun de ceux trouvés.","simple":"Guetter la côte pour les éclats de phares et noter chacun de ceux que tu vois.","deep":"Chaque <code>NimBLEAdvertisedDevice</code> a une adresse, un RSSI et une charge utile. Le scan actif demande aussi des réponses de scan. Les callbacks s'exécutent dans la tâche hôte NimBLE, donc passe les résultats à <code>loop()</code> plutôt que de dessiner là."},"nimble-client":{"short":"La carte en visiteuse : se connecte à un autre appareil Bluetooth et lit ou écrit ses valeurs.","simple":"S'approcher du panneau d'affichage de quelqu'un d'autre au lieu d'héberger le tien.","deep":"Le rôle central. Connecte-toi, découvre les services (<code>getServices(true)</code>), puis lis, écris ou abonne-toi aux caractéristiques distantes. La connexion et la découverte bloquent, donc B8 les fait dans une tâche de travail."},"nimble-conn-info":{"short":"Les détails d'une connexion Bluetooth : qui est connecté, comment elle est sécurisée, quelle taille peut avoir un paquet.","simple":"Le badge du visiteur : son nom, s'il a montré une pièce d'identité, et combien il peut porter d'un coup.","deep":"Passé aux callbacks comme <code>onConnect</code> et <code>onAuthenticationComplete</code> : l'adresse du pair, le handle de connexion, le MTU, et si la liaison est chiffrée, authentifiée et appairée (bonded)."},"nimble-callbacks":{"short":"Des classes dont tu hérites pour être informé des événements Bluetooth : connexions, déconnexions, écritures, lectures.","simple":"Laisser ton numéro à l'accueil : « appelez-moi quand quelqu'un arrive ».","deep":"Redéfinis seulement les fonctions <code>virtual</code> dont tu as besoin (<code>onConnect</code>, <code>onWrite</code>...), puis enregistre l'objet avec <code>setCallbacks</code>. Elles s'exécutent dans la tâche hôte NimBLE, donc garde-les courtes et sûres vis-à-vis des threads."},"nimble-security":{"short":"Décide comment une liaison Bluetooth est sécurisée : appairage, codes d'accès et appairages mémorisés (bonds).","simple":"La politique de la porte : laisser entrer n'importe qui, demander un code, ou ne laisser entrer que des amis déjà rencontrés.","deep":"<code>setSecurityAuth(bond, mitm, sc)</code> demande l'appairage mémorisé, la protection contre l'homme du milieu et LE Secure Connections ; la capacité d'E/S décide si un code d'accès ou une comparaison oui/non est affiché. Les bonds sont stockés en NVS et survivent aux redémarrages."},"ble-note":{"short":"Le raccourci de ce projet pour ajouter une ligne au journal d'activité des labos Bluetooth.","simple":"Un petit mot dans le cahier de labo que l'écran et le journal série montrent tous les deux.","deep":"Une macro de <code>kit/lib/ble-kit/src/ble_link.h</code> qui se développe en <code>::ble::activity().add(::ble::Act::kind, ...)</code> : une entrée à la printf dans un tampon circulaire protégé par une section critique, pour que les callbacks de la tâche NimBLE puissent écrire en sécurité."},"i2s-channel":{"short":"Met en place un canal sonore I2S vers un microphone numérique ou un amplificateur de haut-parleur.","simple":"Poser un tapis roulant pour le son : une horloge donne le rythme, et un nombre voyage pour chaque échantillon.","deep":"Le pilote I2S d'ESP-IDF 5 : <code>i2s_new_channel</code> crée des canaux TX et/ou RX, <code>i2s_channel_init_std_mode</code> règle la fréquence d'échantillonnage, la largeur de bits et les broches (format I2S Philips standard), <code>i2s_channel_enable</code> démarre les horloges et le DMA."},"i2s-read-write":{"short":"Prend des échantillons du microphone, ou en donne au haut-parleur, via le canal I2S.","simple":"Prendre des colis sur le tapis roulant, ou les y poser.","deep":"<code>i2s_channel_read(handle, buf, bytes, &amp;got, timeoutMs)</code> copie depuis les tampons DMA, en attendant si aucun n'est prêt. Les écritures attendent tant que le DMA est plein, donc une tâche de haut-parleur tourne exactement aussi vite que le son se joue."}}`),topics:{basics:{title:`Briques de base`,blurb:`Les petits symboles qui font les calculs, les comparaisons et les choix dans chaque ligne.`},types:{title:`Types de valeurs`,blurb:`Nombres entiers, décimaux, texte et oui/non : ce que peut contenir chaque boîte.`},flow:{title:`Décider et répéter`,blurb:`Comment le code choisit un chemin, boucle et termine un travail.`},functions:{title:`Fonctions`,blurb:`Des recettes nommées que le code peut exécuter, de setup() et loop() aux minuscules lambdas.`},memory:{title:`Mémoire et const`,blurb:`Où vivent les valeurs, comment les pointer et comment les empêcher de changer.`},classes:{title:`Types que tu construis`,blurb:`Structs, classes, enums et namespaces : tes propres sortes de choses.`},modern:{title:`C++ moderne`,blurb:`Constantes de compilation, templates, casts et les aides de la bibliothèque standard.`},preprocessor:{title:`Avant la compilation`,blurb:`Les lignes qui commencent par # et réarrangent le code avant que le compilateur le lise.`},arduino:{title:`Bases d'Arduino`,blurb:`Broches, temps, affichage série et texte : la boîte à outils Arduino de tous les jours.`},esp:{title:`La puce ESP32`,blurb:`Journalisation, mémoire, minuteurs et stockage propres à cette puce.`},rtos:{title:`Faire deux choses à la fois`,blurb:`Les tâches, files et verrous FreeRTOS qui permettent à la carte de faire du multitâche en sécurité.`},libraries:{title:`Bibliothèques`,blurb:`Les aides pour l'écran, le Wi-Fi, le serveur web, le JSON, le Bluetooth et le son utilisées par les labos.`}}};export{e as default};
//# sourceMappingURL=glossary-BNQ-cLWV.js.map